classdef Camera
methods(Static)
 function S=skew(x)
  S=[0 -x(3) x(2);x(3) 0 -x(1);-x(2) x(1) 0];
 end
 function R=exp(v)
  t=norm(v);K=jog.Camera.skew(v);
  if t<1e-8,R=eye(3)+K+.5*K*K;else,R=eye(3)+sin(t)/t*K+(1-cos(t))/t^2*K*K;end
 end
 function v=log(R)
  c=max(-1,min(1,(trace(R)-1)/2));t=acos(c);
  a=[R(3,2)-R(2,3);R(1,3)-R(3,1);R(2,1)-R(1,2)];
  if t<1e-7,v=.5*a;
  elseif pi-t<1e-5
   [V,D]=eig((R+R')/2);[~,i]=max(diag(D));v=t*V(:,i);if dot(v,a)<0,v=-v;end
  else,v=t/(2*sin(t))*a;end
 end
 function J=leftInverse(v)
  t=norm(v);K=jog.Camera.skew(v);
  if t<1e-5,J=eye(3)-.5*K+K*K/12;
  else,J=eye(3)-.5*K+(1/t^2-(1+cos(t))/(2*t*sin(t)))*K*K;end
 end
 function c=truth(cfg)
  x=cfg.camera;c=struct('gamma',x.gamma,'R',jog.Camera.exp(x.rotvec),...
   'phi',log(x.f/x.scale),'kappa',x.kappa,'pp',x.pp,'scale',x.scale);
 end
 function c=step(c,delta)
  c.gamma=c.gamma+delta(1:3);c.R=jog.Camera.exp(delta(4:6))*c.R;
  c.phi=c.phi+delta(7);c.kappa=c.kappa+delta(8);c.pp=c.pp+delta(9:10);
 end
 function [psi,A,B,physical,reason]=evaluate(y,c)
  n=size(y,2);psi=zeros(2*n,1);A=zeros(2*n,10);B=zeros(2*n,5*n);
  physical=true;reason='';ff=exp(c.phi);
  for i=1:n
   d=(y(1:2,i)-c.pp)/c.scale;rr=d'*d;h=1+c.kappa*rr;
   t=c.R*(y(3:5,i)-c.gamma);ii=2*i-1:2*i;jj=5*i-4:5*i;
   if t(3)<=1e-6,physical=false;reason='negative_depth';return;end
   if h<=1e-5 || 1-c.kappa*rr<=1e-5,physical=false;reason='distortion_not_invertible';return;end
   g=t(1:2)/t(3);E=eye(2)/h-2*c.kappa/h^2*(d*d');
   P=[1 0 -g(1);0 1 -g(2)]/t(3);
   psi(ii)=d/h-ff*g;
   A(ii,:)=[-ff*P*c.R,-ff*P*jog.Camera.skew(t),ff*g,rr*d/h^2,E/c.scale];
   B(ii,jj)=[E/c.scale,-ff*P*c.R];
  end
 end
 function uv=project(x,c)
  t=c.R*(x-c.gamma);a=exp(c.phi)*t(1:2,:)./t(3,:);
  disc=1-4*c.kappa*sum(a.^2,1);uv=nan(size(a));good=t(3,:)>0 & disc>0;
  lam=2./(1+sqrt(disc(good)));uv(:,good)=c.pp+c.scale*a(:,good).*lam;
 end
 function geom=geometry(cfg,n,spread,seed)
  rng(seed,'twister');c=jog.Camera.truth(cfg);x=cfg.camera;
  patch=mod(0:n-1,4)+1;signs=[-1 1 -1 1;-1 -1 1 1];
  uv=zeros(2,n);
  for i=1:n
   uv(:,i)=signs(:,patch(i)).*(.12+.88*rand(2,1)).*[x.width;x.height]*x.occupancy/2;
  end
  % Exactly fixed geometry within independent noise/map repeats.
  z=x.mean_depth*(1+spread*(rand(1,n)-.5));
  d=(uv-c.pp)/x.scale;a=d./(1+c.kappa*sum(d.^2,1));
  t=[a/exp(c.phi).*z;z];xyz=c.gamma+c.R'*t;
  geom=struct('truth_camera',c,'y_true',[uv;xyz],'patch_id',patch,...
   'point_id',1:n,'seed',seed,'spread_requested',spread,...
   'depth_actual',z,'depth_cv',std(z,1)/mean(z),...
   'image_hull_fraction',polyarea(uv(1,convhull(uv(1,:),uv(2,:))),uv(2,convhull(uv(1,:),uv(2,:))))/(x.width*x.height));
 end
 function noise=noiseModel(cfg,geom,scale,kind)
  assert(any(strcmp(kind,{'patch','global'})),'Unknown legacy noise kind');
  n=size(geom.y_true,2);x=cfg.camera;
  Ql=zeros(5*n);ratio=x.anisotropy;
  xyzvar=x.local_xyz_std^2*diag([3/(2+ratio^2),3/(2+ratio^2),3*ratio^2/(2+ratio^2)]);
  for i=1:n,jj=5*i-4:5*i;Ql(jj,jj)=blkdiag(x.local_image_std^2*eye(2),xyzvar)*scale^2;end
  if strcmp(kind,'global'),G=zeros(5*n,3);qb=x.global_std^2*scale^2*eye(3);
  else,G=zeros(5*n,12);qb=x.patch_std^2*scale^2*eye(12);end
  for i=1:n
   rr=5*i-2:5*i;if strcmp(kind,'global'),cc=1:3;else,cc=3*geom.patch_id(i)-2:3*geom.patch_id(i);end
   G(rr,cc)=eye(3);
  end
  Qfull=Ql+G*qb*G';F_local=chol(Ql,'lower');Fcommon=G*chol(qb,'lower');
  noise=struct('Q_local',Ql,'G_raw',G,'Q_b',qb,'F_local',F_local,...
   'F_common',Fcommon,'Q_full',Qfull,'kind',kind,'noise_scale',scale);
 end
 function F=factor(noise,method)
  n=size(noise.Q_local,1)/5;
  switch method
   case 'GH_FULL',F=[noise.F_local,noise.F_common];
   case 'GH_LOCAL',F=noise.F_local;
   case 'GH_MARGDIAG'
    F=zeros(5*n);for i=1:n,j=5*i-4:5*i;F(j,j)=chol(noise.Q_full(j,j),'lower');end
   case 'FIXED3D_WLS'
    F=zeros(5*n,2*n);for i=1:n,j=5*i-4:5*i-3;F(j,2*i-1:2*i)=chol(noise.Q_local(j,j),'lower');end
   otherwise,error('Unknown method');
  end
 end
 function pool=initialize(y,cfg)
  % Uses observed points only; no pose/IOP truth is passed to this routine.
  pool={};sc=cfg.camera.scale;n=size(y,2);x=y(3:5,:);
  centre=mean(x,2);sx=sqrt(mean(sum((x-centre).^2,1))/3);
  if sx<=eps,return;end
  xn=(x-centre)/sx;X=[xn;ones(1,n)];Tw=[eye(3)/sx,-centre/sx;0 0 0 1];
  for kap=cfg.nonlinear.kappa_initial
   dd=y(1:2,:)/sc;uu=dd./(1+kap*sum(dd.^2,1));
   D=zeros(2*n,12);
   for i=1:n
    D(2*i-1,:)=[X(:,i)' zeros(1,4) -uu(1,i)*X(:,i)'];
    D(2*i,:)=[zeros(1,4) X(:,i)' -uu(2,i)*X(:,i)'];
   end
   [~,S,V]=svd(D,0);if S(end-1,end-1)<1e-10*S(1,1),continue;end
   P=reshape(V(:,end),4,3)'*Tw;M=P(:,1:3);
   if rcond(M)<1e-12,continue;end
   if det(M)<0,P=-P;M=-M;end
   [Q,R]=qr(flipud(M)');K=fliplr(flipud(R'));Rc=flipud(Q');
   sg=sign(diag(K));sg(sg==0)=1;Ds=diag(sg);K=K*Ds;Rc=Ds*Rc;
   K=K/K(3,3);f=sc*mean([K(1,1),K(2,2)]);
   if f<=cfg.solver.focal_range(1)||f>=cfg.solver.focal_range(2)||det(Rc)<0,continue;end
   c=struct('gamma',-M\P(:,4),'R',Rc,'phi',log(f/sc),'kappa',kap,'pp',sc*K(1:2,3),'scale',sc);
   if any(abs(c.pp)>cfg.solver.principal_point_absmax),continue;end
   [~,~,~,ok]=jog.Camera.evaluate(y,c);if ok,pool{end+1}=c;end %#ok<AGROW>
  end
 end
 function e=error(c,truth)
  e=[c.gamma-truth.gamma;jog.Camera.log(c.R*truth.R');c.phi-truth.phi;c.kappa-truth.kappa;c.pp-truth.pp];
 end
end
end

classdef Core
methods(Static)
 function s=seed(cfg,suite,condition,trial)
  s=cfg.master_seed+suite*10000000+condition*10000+trial;
  assert(s<2^32 && trial<10000,'Seed range exceeded.');
 end
 function [Ni,H,rankA,condition]=normal(A,tol)
  if nargin<2,tol=1e-10;end
  scale=sqrt(sum(A.^2,1));
  if any(scale==0),error('jog:rank_deficient','Zero design column.');end
  An=A./scale; sv=svd(An,'econ'); rankA=sum(sv>tol*sv(1));
  condition=sv(1)/sv(end);
  if rankA<size(A,2),error('jog:rank_deficient','Scaled design rank deficient.');end
  Nn=An'*An; R=chol((Nn+Nn')/2);
  Ci=R\(R'\eye(size(Nn))); D=diag(1./scale);
  Ni=D*Ci*D; Ni=(Ni+Ni')/2; H=An*Ci*An'; H=(H+H')/2;
 end
 function d=linear(A,U,Qb)
  [Ni,H,ra,ca]=jog.Core.normal(A);
  T=Ni*A'*U; V=U-A*T; J=V'*V;
  if isempty(U)
   Pb=zeros(0); K=zeros(0); Omega=eye(size(A,1));
  else
   qi=Qb\eye(size(Qb)); Pb=(qi+J)\eye(size(Qb)); Pb=(Pb+Pb')/2;
   C=chol(Qb,'lower'); K=C'*J*C; Omega=eye(size(A,1))+U*Qb*U';
  end
  W=Ni*A'-T*Pb*V'; Sigma=Ni+T*Pb*T'; Sigma=(Sigma+Sigma')/2;
  Lo=chol((Omega+Omega')/2,'lower'); Ao=Lo\A;
  [direct,~,~,~]=jog.Core.normal(Ao); Wdirect=direct*Ao'/Lo;
  d=struct('A',A,'U',U,'Qb',Qb,'N_local',A'*A,'N_full',Ao'*Ao,...
   'N_local_inverse',Ni,'H',H,'T',T,'V',V,'J',J,'Q_b_given_r',Pb,...
   'K',K,'learning_spectrum',sort(max(0,eig((K+K')/2)),'descend'),...
   'Sigma',Sigma,'Sigma_direct',direct,'W',W,'W_direct',Wdirect,...
   'Omega',Omega,'rank_A',ra,'condition_A_scaled',ca);
 end
 function [v,spectrum]=inflation(d,L)
  c0=L*d.N_local_inverse*L'; dc=L*d.T*d.Q_b_given_r*d.T'*L';
  C=chol((c0+c0')/2,'lower'); M=C\dc/C';
  spectrum=1+sort(max(0,eig((M+M')/2)),'descend');v=max(spectrum);
 end
 function e=relative(A,B)
  e=norm(A-B,'fro')/max([1,norm(A,'fro'),norm(B,'fro')]);
 end
 function x=chi2(p,df)
  x=2*gammaincinv(p,df/2);
 end
 function ci=wilson(k,n)
  if n==0,ci=[NaN NaN];return;end
  z=1.95996398454005; ph=k/n; den=1+z*z/n;
  mid=(ph+z*z/(2*n))/den;
  half=z*sqrt(ph*(1-ph)/n+z*z/(4*n*n))/den; ci=[mid-half mid+half];
 end
 function s=summarize(errors,covariances,valid,nominal)
  % Columns are independent map realizations. Failures remain in total N.
  [p,N]=size(errors); ix=find(valid & all(isfinite(errors),1)); nv=numel(ix);
  s=struct('n_total',N,'n_valid',nv,'failure_rate',1-nv/N,...
   'bias',nan(p,1),'covariance',nan(p),'std',nan(p,1),'std_ci',nan(p,2),...
   'rmse',NaN,'mean_predicted_covariance',nan(p),'predicted_std',nan(p,1),...
   'nominal',nominal,'coverage_conditional',nan(size(nominal)),...
   'coverage_operational',zeros(size(nominal)),'coverage_wilson',nan(numel(nominal),2),...
   'nees',nan(1,N),'n_covariance_valid',0);
  if nv==0,return;end
  X=errors(:,ix); s.bias=mean(X,2); s.rmse=sqrt(mean(sum(X.^2,1)));
  if nv>=2
   xc=X-s.bias; s.covariance=xc*xc'/(nv-1); s.std=sqrt(max(0,diag(s.covariance)));
   mu4=mean(xc.^4,2); sevar=sqrt(max(0,(mu4-((nv-3)/(nv-1))*s.std.^4)/nv));
   s.std_ci=sqrt(max(0,[s.std.^2-1.96*sevar,s.std.^2+1.96*sevar]));
  end
  Cs=zeros(p); nc=0;
  for k=ix
   if size(covariances,3)==1,C=covariances;else,C=covariances(:,:,k);end
   if any(~isfinite(C(:))),continue;end
   [R,flag]=chol((C+C')/2);if flag~=0,continue;end
   s.nees(k)=sum((R'\errors(:,k)).^2); Cs=Cs+C;nc=nc+1;
  end
  s.n_covariance_valid=nc;
  if nc>0
   s.mean_predicted_covariance=Cs/nc;s.predicted_std=sqrt(max(0,diag(Cs/nc)));
   for a=1:numel(nominal)
    hits=sum(s.nees<=jog.Core.chi2(nominal(a),p));
    s.coverage_conditional(a)=hits/nc;s.coverage_operational(a)=hits/N;
    s.coverage_wilson(a,:)=jog.Core.wilson(hits,nc);
   end
  end
 end
 function x=quantile(v,p)
  v=sort(v(isfinite(v))); if isempty(v),x=NaN;return;end
  q=1+(numel(v)-1)*p;lo=floor(q);hi=ceil(q);x=v(lo)+(q-lo)*(v(hi)-v(lo));
 end
end
end

function out=linear_suite(id,cfg)
%LINEAR_SUITE Fixed-design experiments J00--J06 (J03 is invariance).
out=struct('id',id,'layer','L1 fixed-design Gaussian','conditions',{{}},'notes','');
switch id
 case 'J00'
  rng(jog.Core.seed(cfg,0,0,0),'twister');C=cfg.identity_cases;
  names={'GLS estimate','GLS covariance','Mixed inverse','Orthogonality','Kernel'};
  err=zeros(C,numel(names));cond=zeros(C,1);designs=cell(C,1);
  for c=1:C
   [O,~]=qr(randn(24));A=O(:,1:4)*diag(.5+2*rand(4,1));T=randn(4,5);
   V=O(:,5:9)*randn(5);V(:,end)=0;U=A*T+V;Z=randn(5);Q=Z*Z'/5+eye(5);
   d=jog.Core.linear(A,U,Q);mix=[A'*A A'*U;U'*A U'*U+(Q\eye(5))];
   expected=[d.Sigma -d.T*d.Q_b_given_r;-d.Q_b_given_r*d.T' d.Q_b_given_r];
   h=[zeros(4,1);1];
   err(c,:)=[jog.Core.relative(d.W,d.W_direct),jog.Core.relative(d.Sigma,d.Sigma_direct),...
    jog.Core.relative(mix\eye(9),expected),norm(A'*d.V,'fro'),norm([A U]*[-d.T*h;h])];
   cond(c)=d.condition_A_scaled;designs{c}=d;
  end
  assert(max(err(:))<1e-8,'J00 algebra verification failed.');
  out.errors=err;out.error_names=names;out.condition=cond;out.designs=designs;
  out.notes='Deterministic matrix identities. Not a camera accuracy experiment.';
 case 'J01'
  g=jog.Camera.geometry(cfg,40,.15,jog.Core.seed(cfg,1,0,0));
  no=jog.Camera.noiseModel(cfg,g,1,'patch');[~,A,B]=jog.Camera.evaluate(g.y_true,g.truth_camera);
  Sl=B*no.Q_local*B';Cl=chol(Sl,'lower');U=Cl\(B*no.G_raw);
  cols={1:6,1:7,1:8,1:10};names={'EOP (6)','+ focal (7)','+ distortion (8)','+ principal point (10)'};
  old=[];
  for c=1:4
   d=jog.Core.linear(Cl\A(:,cols{c}),U,no.Q_b);L=[eye(3),zeros(3,numel(cols{c})-3)];
   [inflation,spectrum]=jog.Core.inflation(d,L);
   nullTolerance=1e-9*max(1,norm(d.V,2));Z=null(d.V,nullTolerance);
   defect=norm(L*d.T*Z,'fro');
   rec=struct('name',names{c},'parameter_columns',cols{c},'design',d,'L_target',L,...
    'position_variance_inflation',inflation,'position_inflation_spectrum',spectrum,...
    'J_drop_min_eigenvalue',NaN,'null_V',Z,'null_V_absolute_tolerance',nullTolerance,...
    'target_estimability_defect',defect,'target_estimable_against_fixed_common_effects',...
    defect<=1e-8*max(1,norm(L*d.T,'fro')));
   if c>1
    rec.J_drop_min_eigenvalue=min(eig((old-d.J+old'-d.J')/2));
    assert(rec.J_drop_min_eigenvalue>=-1e-8*max(1,norm(old,2)),'J01 information nesting failed.');
   end
   out.conditions{c}=rec;old=d.J;
  end
  out.geometry=g;out.noise=no;
  out.notes='Same truth design, observations, loading and LOCAL whitening; only IOP columns are added.';
 case 'J02'
  count=0;
  for rho=cfg.linear.rho
   for s=cfg.linear.s
    count=count+1;A=[sqrt(s);0];U=[sqrt(s) 0;0 sqrt(s)];Q=.04*[1 rho;rho 1];
    d=jog.Core.linear(A,U,Q);rec=mc(d,cfg,2,count);
    rec.rho=rho;rec.s=s;rec.target_floor=.04*(1-rho^2);
    rec.prediction_errors=rec.b-d.Q_b_given_r*d.V'*rec.residual;
    rec.prediction_covariance=cov(rec.prediction_errors');
    out.conditions{count}=rec;
   end
  end
  out.notes='Compact sufficient contrasts of s repeated observations; one hidden and one learned mode. All common effects are redrawn per trial.';
 case 'J03'
  rng(jog.Core.seed(cfg,3,0,0),'twister');err=zeros(cfg.identity_cases,3);records=cell(cfg.identity_cases,1);
  for c=1:cfg.identity_cases
   A=randn(20,4);U=randn(20,3);Q=randn(3);Q=Q*Q'+eye(3);d=jog.Core.linear(A,U,Q);
   [Mb,~]=qr(randn(3));Mb=Mb*diag([.1 2 10]);dp=jog.Core.linear(A,U/Mb,Mb*Q*Mb');
   L=[eye(2) zeros(2)];C=[2 .3;-.2 .5];
   [~,sp0]=jog.Core.inflation(d,L);[~,sp1]=jog.Core.inflation(dp,L);[~,sp2]=jog.Core.inflation(d,C*L);
   err(c,:)=[jog.Core.relative(d.learning_spectrum,dp.learning_spectrum),...
    jog.Core.relative(sp0,sp1),jog.Core.relative(sp0,sp2)];
   records{c}=struct('original',d,'transformed',dp,'M_b',Mb,'L',L,'target_transform',C,...
    'inflation_spectra',[sp0 sp1 sp2]);
  end
  assert(max(err(:))<1e-8,'J03 invariance failed.');out.errors=err;out.records=records;
  out.notes='Coordinate-change identities. Generalized eigenvalues, not individual covariance entries, are invariant.';
 case 'J04'
  s=100;A=[sqrt(s);0;0];U=[sqrt(s);0;0];
  for c=1:numel(cfg.linear.tau)
   tau=cfg.linear.tau(c);d=jog.Core.linear(A,U,.04+tau);
   N=cfg.mc_linear;b=zeros(1,N);noise=zeros(3,N);base=zeros(1,N);added=zeros(1,N);seeds=zeros(1,N);
   for k=1:N
    seeds(k)=jog.Core.seed(cfg,4,0,k);rng(seeds(k),'twister');
    base(k)=.2*randn;added(k)=randn;noise(:,k)=randn(3,1);b(k)=base(k)+sqrt(tau)*added(k);
   end
   z=U*b+noise;estimate=d.W*z;r=(eye(3)-d.H)*z;
   rec=struct('tau',tau,'s',s,'design',d,'seed',seeds,'b',b,'base_b',base,...
    'added_standard_normal',added,'noise',noise,'observations',z,'estimate',estimate,'residual',r,...
    'summary',jog.Core.summarize(estimate,d.Sigma,true(1,N),cfg.nominal),...
    'residual_energy',sum(r.^2,1));
   out.conditions{c}=rec;
  end
  out.notes='Paired base errors across tau; adding an invisible common effect leaves residuals identical, but changes target variance.';
 case 'J05'
  count=0;qb=2;
  for rate=cfg.linear.rates
   for s=cfg.linear.s
    count=count+1;delta=s^(-rate);A=[sqrt(s);0];U=[sqrt(s);sqrt(s)*delta];
    d=jog.Core.linear(A,U,qb);rec=mc(d,cfg,5,count);
    rec.s=s;rec.rate=rate;rec.delta=delta;rec.EAR=1/(1+delta^2);
    if rate<.5,rec.limit=0;elseif rate==.5,rec.limit=1/(1/qb+1);else,rec.limit=qb;end
    out.conditions{count}=rec;
   end
  end
  out.notes='Exact compact Gaussian experiment with information growth s; EAR is geometric, not an uncertainty probability.';
 case 'J06'
  out.layer='L2 reduced pinhole, fixed Jacobian';f=cfg.plane.f;gz=cfg.plane.gamma_z;o=-10;n=30;
  spread=[.005 .01 .02 .05 .1 .2 .4 .6];theta=2*pi*(0:n-1)/n;rho=3*[cos(theta);sin(theta)];
  for c=1:numel(spread)
   z=20*(1+spread(c)*linspace(-.5,.5,n));Z=gz+z;
   a=f*rho./z.^2/cfg.plane.image_std;
   A1=a(:);A2=[a(:),reshape(a.*z,[],1)];U=reshape(a.*(Z-o),[],1);
   dk=jog.Core.linear(A1,U,.01^2);df=jog.Core.linear(A2,U,.01^2);
   w=sum(a.^2,1);Zw=sum(w.*Z)/sum(w);formula=sum(w.*(Z-Zw).^2);
   assert(abs(dk.J-formula)<1e-7*max(1,formula));assert(norm(df.V)<1e-8*norm(U));
   out.conditions{c}=struct('spread',spread(c),'depths',z,'rho',rho,'known_f',dk,'free_f',df,...
    'formula_J',formula,'loading_identity_error',norm(U-A2*[gz-o;1]),'origin_z',o);
  end
  out.notes='Directional depth scale, not rigid TLS registration. Same pointwise local image whitening in fixed/free focal comparison.';
 otherwise,error('Unsupported linear experiment %s',id);
end
end

function rec=mc(d,cfg,suite,condition)
N=cfg.mc_linear;n=size(d.A,1);r=size(d.U,2);
b=zeros(r,N);ee=zeros(n,N);seed=zeros(1,N);C=chol(d.Qb,'lower');
for k=1:N
 seed(k)=jog.Core.seed(cfg,suite,condition,k);rng(seed(k),'twister');
 b(:,k)=C*randn(r,1);ee(:,k)=randn(n,1);
end
z=d.U*b+ee;estimate=d.W*z;residual=(eye(n)-d.H)*z;
rec=struct('design',d,'seed',seed,'b',b,'noise',ee,'observations',z,...
 'truth_parameter',zeros(size(d.A,2),1),'estimate',estimate,'residual',residual,...
 'summary',jog.Core.summarize(estimate,d.Sigma,true(1,N),cfg.nominal));
end

function out=nonlinear_suite(cfg,checkpoint,previous)
%NONLINEAR_SUITE J09: practical observed-data initialization and full GHM.
if nargin<2,checkpoint=[];end
out=struct('id','J09','layer','L3 full nonlinear division camera','conditions',{{}},...
 'notes','Known oracle covariance; observed DLT initialization unless explicitly tagged oracle_local.');
cases={};base=cfg.nonlinear;
for a=base.noise_scales,cases{end+1}=spec('noise_scale',base.baseline_points,base.baseline_spread,a,'patch',a);end
for a=base.depth_spreads
 if abs(a-base.baseline_spread)>1e-12,cases{end+1}=spec('depth_spread',base.baseline_points,a,1,'patch',a);end
end
for a=base.point_counts
 if a~=base.baseline_points,cases{end+1}=spec('point_count',a,base.baseline_spread,1,'patch',a);end
end
for a=base.point_counts,cases{end+1}=spec('global_translation',a,base.baseline_spread,1,'global',a);end
methods=base.methods;
if nargin>=3 && ~isempty(previous),out=previous;end
start=numel(out.conditions)+1;
for ci=start:numel(cases)
 sp=cases{ci};fprintf('  J09 condition %d/%d: %s = %g\n',ci,numel(cases),sp.sweep,sp.x);
 % Geometry uses a namespace disjoint from the per-trial noise seeds.
 gs=cfg.master_seed+200000000+sp.n*1000+round(1000*sp.depth_spread);
 g=jog.Camera.geometry(cfg,sp.n,sp.depth_spread,gs);truth=g.truth_camera;
 no=jog.Camera.noiseModel(cfg,g,sp.noise_scale,sp.kind);N=cfg.mc_nonlinear;nm=numel(methods);
 obs=zeros(5,sp.n,N);localerr=zeros(5*sp.n,N);b=zeros(size(no.Q_b,1),N);seeds=zeros(1,N);
 pools=cell(1,N);runs=cell(nm,N);esterror=nan(10,N,nm);covcommon=nan(10,10,N,nm);covnative=covcommon;
 valid=false(nm,N);factor=cell(1,nm);references=cell(1,nm);
 [~,A0,B0]=jog.Camera.evaluate(g.y_true,truth);
 for mi=1:nm
  factor{mi}=jog.Camera.factor(no,methods{mi});Sm=B0*(factor{mi}*factor{mi}')*B0';
  Lm=chol((Sm+Sm')/2,'lower');[C,~,~,~]=jog.Core.normal(Lm\A0,cfg.solver.rank_tolerance);
  W=C*(Lm\A0)'/Lm*B0;
  references{mi}=struct('nominal_covariance',C,'actual_sampling_covariance',W*no.Q_full*W',...
   'sensitivity',W,'design_is_oracle',true);
 end
 for k=1:N
  seeds(k)=jog.Core.seed(cfg,9,ci,k);rng(seeds(k),'twister');
  localerr(:,k)=no.F_local*randn(5*sp.n,1);b(:,k)=chol(no.Q_b,'lower')*randn(size(no.Q_b,1),1);
  obs(:,:,k)=g.y_true+reshape(localerr(:,k)+no.G_raw*b(:,k),5,[]);
  if strcmp(base.initialization,'observed_DLT_multistart')
   pool=jog.Camera.initialize(obs(:,:,k),cfg);
  elseif strcmp(base.initialization,'oracle_local')
   pool={truth}; % Explicit diagnostic, separately tagged in output.
  else,error('Unknown initialization mode.');end
  pools{k}=pool;
  for mi=1:nm
   r=jog.solve_camera(obs(:,:,k),factor{mi},pool,cfg);
   if ~isempty(r.camera)
    err=jog.Camera.error(r.camera,truth);esterror(:,k,mi)=err;
    r.error_truth_coordinates=err;r.nees_difference_at_estimate=-err;
   end
   valid(mi,k)=r.success;
   if r.success
    covnative(:,:,k,mi)=r.covariance;
    T=eye(10);T(4:6,4:6)=jog.Camera.leftInverse(esterror(4:6,k,mi));
    covcommon(:,:,k,mi)=T*r.covariance*T';
    r.covariance_common_error_coordinates=covcommon(:,:,k,mi);
    if strcmp(methods{mi},'GH_FULL')
     r.predicted_common=chol(no.Q_b,'lower')*r.latent_error(5*sp.n+1:end);
     [~,Ae,Be]=jog.Camera.evaluate(r.adjusted_observations,r.camera);
     Le=chol(Be*no.Q_local*Be','lower');dg=jog.Core.linear(Le\Ae,Le\(Be*no.G_raw),no.Q_b);
     r.common_diagnostics=rmfield(dg,{'H','Omega','W','W_direct','A','U'});
    end
   end
   runs{mi,k}=r;
  end
  if mod(k,max(1,floor(N/5)))==0,fprintf('    %d/%d maps done\n',k,N);end
 end
 summaries=cell(1,nm);
 for mi=1:nm
  e=esterror(:,:,mi);S=covcommon(:,:,:,mi);Sn=covnative(:,:,:,mi);
  % Scalar error components use a common truth-anchored chart for moments.
  ss=jog.Core.summarize(e,S,valid(mi,:),cfg.nominal);
  native=jog.Core.summarize(-e,Sn,valid(mi,:),cfg.nominal);
  ss.coverage_conditional=native.coverage_conditional;ss.coverage_operational=native.coverage_operational;
  ss.coverage_wilson=native.coverage_wilson;ss.nees=native.nees;
  ss.position=jog.Core.summarize(e(1:3,:),S(1:3,1:3,:),valid(mi,:),cfg.nominal);
  ss.eop=jog.Core.summarize(e(1:6,:),S(1:6,1:6,:),valid(mi,:),cfg.nominal);
  enative=jog.Core.summarize(-e(1:6,:),Sn(1:6,1:6,:),valid(mi,:),cfg.nominal);
  ss.eop.coverage_conditional=enative.coverage_conditional;
  ss.eop.coverage_operational=enative.coverage_operational;
  ss.eop.coverage_wilson=enative.coverage_wilson;ss.eop.nees=enative.nees;
  ss.rotation_rmse_deg=sqrt(mean(sum(e(4:6,valid(mi,:)).^2,1)))*180/pi;
  ss.focal_relative_rmse=sqrt(mean((exp(e(7,valid(mi,:)))-1).^2));
  ss.raw_reprojection_coordinate_rmse=cellfun(@(r)r.raw_reprojection_coordinate_rmse,runs(mi,:));
  ss.position_error_norm=sqrt(sum(e(1:3,:).^2,1));
  ss.ellipsoid_maxaxis95=nan(1,N);ss.ellipsoid_volume95=nan(1,N);
  for k=find(valid(mi,:))
   ev=eig(Sn(1:3,1:3,k));axes95=sqrt(jog.Core.chi2(.95,3)*max(0,ev));
   ss.ellipsoid_maxaxis95(k)=max(axes95);ss.ellipsoid_volume95(k)=4*pi/3*prod(axes95);
  end
  ss.median_maxaxis95=jog.Core.quantile(ss.ellipsoid_maxaxis95,.5);
  ss.mean_seconds=mean(cellfun(@(r)r.elapsed_seconds,runs(mi,:)));
  ss.status=cellfun(@(r)r.status,runs(mi,:),'UniformOutput',false);
  summaries{mi}=ss;
 end
 out.conditions{ci}=struct('spec',sp,'geometry_id',gs,'geometry',g,'noise_model',no,'methods',{methods},...
  'oracle_reference',{references},'covariance_factors',{factor},'trial_id',1:N,'map_id',1:N,'seed',seeds,...
  'observations',obs,'true_local_errors',localerr,'true_common_effects',b,...
  'initialization_mode',base.initialization,'shared_initializer_pool',{pools},'runs',{runs},...
  'errors',esterror,'covariance_common',covcommon,'covariance_at_estimate',covnative,...
  'valid',valid,'summary',{summaries});
 if ~isempty(checkpoint),checkpoint(out);end
end
end
