 idx=find(strcmp({info.Attributes.Name},name),1);
 if ~isempty(idx),a=info.Attributes(idx).Value;if isstring(a),a=char(a);end,end
end
function n=count(file,path)
 info=h5info(file,path);n=prod(info.Dataspace.Size);
end
end
