function result=solve_general(y,F,pool,cfg)
%SOLVE_CAMERA Local constrained adjustment in latent errors e=F*v.
% All methods share exactly the same observed-data initializer pool.
% Minimizes .5*||v||^2 subject to psi(y-F*v,c)=0. Redundant full-covariance
% factors are valid; their minimum-norm latent representation is selected.
t=tic; candidates=cell(size(pool));best=Inf;selected=0;
for j=1:numel(pool)
 candidates{j}=one(y,F,pool{j},cfg);
 if candidates{j}.success && candidates{j}.cost<best,best=candidates{j}.cost;selected=j;end
end
if selected==0
 result=blank(y,F);result.status='no_valid_initializer';
 if ~isempty(pool)
  result.status='nonconverged_all_candidates';
  scores=cellfun(@(x)x.final_merit,candidates);[~,j]=min(scores);
  result=candidates{j};result.success=false;result.status=['all_candidates_failed:' result.status];
 end
else,result=candidates{selected};end
result.selected_candidate=selected;result.candidate_count=numel(pool);
summaries=cell(size(candidates));
for j=1:numel(candidates)
 cc=candidates{j};summaries{j}=struct('camera',cc.camera,'success',cc.success,'status',cc.status,...
 'cost',cc.cost,'iterations',cc.iterations,'constraint_inf',cc.constraint_inf,'history',cc.history,'physical_valid',cc.physical_valid,...
 'active_parameter_bound',cc.active_parameter_bound);
end
result.candidates=summaries;result.elapsed_seconds=toc(t);
end

function r=one(y,F,c,cfg)
opt=cfg.solver;free=1:10;
if isfield(opt,'free_columns'),free=opt.free_columns;end
if isfield(opt,'focal_direct')&&opt.focal_direct,opt.parameter_scale(7)=c.scale*exp(c.phi);end
v=zeros(size(F,2),1);rho=1;history=nan(opt.max_iterations,7);
r=blank(y,F);r.camera=c;Y=y(:);status='nonconverged';it=0;
for it=1:opt.max_iterations
 mu=reshape(Y-F*v,5,[]);[psi,A,B,ok,reason]=jog.Camera.evaluate(mu,c);
 if ~ok,status=reason;break;end
 A=chartA(A,c,opt);BF=B*F;S=BF*BF';[Cs,flag]=chol((S+S')/2,'lower');
 if flag,status='singular_condition_covariance';break;end
 w=psi+BF*v;Aw=Cs\A;ww=Cs\w;
 try,[Ni,~,rankA,condA]=jog.Core.normal(Aw(:,free),opt.rank_tolerance);
 catch,status='rank_deficient';break;end
 delta=zeros(10,1);delta(free)=Ni*Aw(:,free)'*ww;lambda=Cs'\(Cs\(w-A*delta));vnew=BF'*lambda;dv=vnew-v;
 scaled=max(abs(delta)./opt.parameter_scale);closure=norm(psi,inf);
 if scaled<opt.step_tolerance && norm(dv)/max(1,norm(v))<opt.step_tolerance && closure<opt.constraint_tolerance
  status='success';history(it,:)=[.5*(v'*v),closure,scaled,0,condA,norm(dv),rho];break;
 end
 rho=max(rho,1.5*norm(lambda,inf)+1);merit=.5*(v'*v)+rho*norm(psi,1);
 slope=v'*dv-rho*norm(psi,1);accepted=false;step=1;
 for ls=1:opt.max_linesearch
  trial=chartStep(c,step*delta,opt);vt=v+step*dv;
  if ~bounds(trial,opt),step=step/2;continue;end
  [pt,~,~,good]=jog.Camera.evaluate(reshape(Y-F*vt,5,[]),trial);
  if good
   mt=.5*(vt'*vt)+rho*norm(pt,1);
   if mt<=merit+1e-4*step*min(slope,-eps*max(1,merit))
    accepted=true;break;
   end
  end
  step=step/2;
 end
 history(it,:)=[.5*(v'*v),closure,scaled,step,condA,norm(dv),rho];
 if ~accepted
  % Accept stationarity at a stricter feasibility threshold only; no silent success.
  if closure<opt.constraint_tolerance && scaled<10*opt.step_tolerance && norm(dv)/max(1,norm(v))<10*opt.step_tolerance
   status='success';
  else,status='line_search_failed';end
  break;
 end
 c=trial;v=vt;
end
r.camera=c;r.latent_error=v;r.adjusted_observations=reshape(Y-F*v,5,[]);
r.observation_correction=reshape(F*v,5,[]);r.cost=.5*v'*v;r.status=status;
r.iterations=it;r.history=history(1:it,:);r.history_columns={'cost','closure_inf','scaled_step','line_step','scaled_condition','latent_step','merit_penalty'};
[psi,A,B,ok,~]=jog.Camera.evaluate(r.adjusted_observations,c);
r.constraint_inf=norm(psi,inf);r.final_merit=r.cost+rho*norm(psi,1);
r.success=strcmp(status,'success') && ok;r.physical_valid=ok;
r.active_parameter_bound=nearBounds(c,opt);
if r.success
 A=chartA(A,c,opt);S=B*(F*F')*B';[Cs,flag]=chol((S+S')/2,'lower');
 if ~flag
  try
   [Cf,~,ra,cond]=jog.Core.normal(Cs\A(:,free),opt.rank_tolerance);C=zeros(10);C(free,free)=Cf;
   T=eye(10);if isfield(opt,'focal_direct')&&opt.focal_direct,T(7,7)=1/(c.scale*exp(c.phi));end
   r.covariance=T*C*T';r.rank=ra;r.condition_scaled=cond;
   r.sensitivity=T*C*(Cs\A)'/Cs*B;
   lambda=S\(B*F*v);r.stationarity_norm=norm(A'*lambda,inf);
  catch,r.success=false;r.status='covariance_unavailable';end
 else,r.success=false;r.status='singular_condition_covariance';end
end
if r.active_parameter_bound,r.success=false;r.status='active_parameter_bound';end
uv=jog.Camera.project(y(3:5,:),c);r.raw_reprojection=y(1:2,:)-uv;
r.raw_reprojection_coordinate_rmse=sqrt(mean(r.raw_reprojection(:).^2));
if ~cfg.save_candidate_history,r.history=[];end
end
function r=blank(y,F)
r=struct('success',false,'status','not_run','camera',[],...
 'covariance',nan(10),'sensitivity',[],'rank',NaN,'condition_scaled',NaN,...
 'latent_error',nan(size(F,2),1),'adjusted_observations',nan(size(y)),...
 'observation_correction',nan(size(y)),'cost',Inf,'final_merit',Inf,...
 'iterations',0,'history',[],'constraint_inf',Inf,'physical_valid',false,...
 'active_parameter_bound',false,'stationarity_norm',NaN,...
 'raw_reprojection',nan(2,size(y,2)),'raw_reprojection_coordinate_rmse',NaN);
end
function yes=bounds(c,opt)
f=c.scale*exp(c.phi);yes=isfinite(f)&&f>opt.focal_range(1)&&f<opt.focal_range(2)...
 &&c.kappa>opt.kappa_range(1)&&c.kappa<opt.kappa_range(2)&&all(abs(c.pp)<opt.principal_point_absmax);
end
function yes=nearBounds(c,opt)
f=c.scale*exp(c.phi);tol=1e-6;
yes=min(abs(f-opt.focal_range))<tol || min(abs(c.kappa-opt.kappa_range))<tol || any(abs(abs(c.pp)-opt.principal_point_absmax)<tol);
end

function A=chartA(A,c,opt)
if isfield(opt,'focal_direct')&&opt.focal_direct,A(:,7)=A(:,7)/(c.scale*exp(c.phi));end
end
function c=chartStep(c,delta,opt)
if isfield(opt,'focal_direct')&&opt.focal_direct
 f=c.scale*exp(c.phi);fp=f+delta(7);
 if fp<=0,c.phi=NaN;return;end
 delta(7)=log(fp/f);
end
c=jog.Camera.step(c,delta);
end

% Full legacy + recommended revision experiments; can take hours and many GiB.
% Inspect smoke/pilot runtime and disk estimates first. No results are presumed.
cfg=jog_config_v2('paper');
run_jog_v2(cfg);

% Recovery of completed simulations. Select the OLD paper run folder.
% Run this script from the NEW v2.1 package folder after stopping old analysis.
source=uigetdir(pwd,'Select OLD paper run folder containing checkpoint.mat');
if isequal(source,0),return;end
% Stable destination: running this script again resumes packing/analysis.
[~,runname]=fileparts(source);
destination=fullfile(pwd,'results',[runname '_recovered']);
jog_recover_v2(source,destination);

% Convert your existing output.mat, preserve raw data, run only new suites.
[file,folder]=uigetfile('*.mat','Select the existing v1 output.mat');
if isequal(file,0),return;end
destination=fullfile(pwd,'results',['import_' datestr(now,'yyyymmdd_HHMMSS')]);
old=jog_import_v1(fullfile(folder,file),destination);
jog_analyze_v2(old.output_file,{'D01','D02','D03','D04','J15'});
cfg=jog_config_v2('paper');
cfg.enabled={'J10','J11','J12','J13','J14','J15'};
cfg.source_runs={old.output_file};cfg.j10.geometry_source_run=old.output_file;
run_jog_v2(cfg);

% Open this folder as MATLAB Current Folder and run this script.
cfg=jog_config_v2('smoke');
run_jog_v2(cfg);

function result=jog_advanced_v2(file,opt)
%JOG_ADVANCED_V2 Optional J16: explicit modules, no automatic expensive runs.
% Modules: hessian, reparameterization, bootstrap, profile.
o=jog2.Store.metadata(file);cfg=o.config;if nargin<2,opt=cfg.j16;end
assert(all(ismember(opt.modules,{'hessian','reparameterization','bootstrap','profile'})),'Unknown J16 module');
chosen=[];
for delta=[.15 .02]
 ix=find(cellfun(@(c)c.spec.n==30&&abs(c.spec.depth_spread-delta)<1e-12&&c.spec.noise_scale==1,o.conditions),1);
 if ~isempty(ix),chosen(end+1)=ix;end
end
if ~isfield(o,'extra_datasets'),o.extra_datasets={};end
result=struct('status','complete','modules',{opt.modules},'conditions',{{}},...
 'limitations','Conditional valid-fit diagnostics; bootstrap/LR are not finite-sample guarantees.');
for ii=1:numel(chosen)
 c=o.conditions{chosen(ii)};d=jog2.Store.design(file,c);m=find(strcmp(d.methods,'GH_FULL'),1);
 if isempty(m),continue;end
 F=d.covariance_factors{m};truth=d.geometry.truth_camera;rout=struct('source_condition',c.prefix);
 if ismember('hessian',opt.modules)
  F0=F/d.spec.noise_scale;D=size(F0,2);limit=D;
  if isfield(opt,'max_directions'),limit=min(limit,opt.max_directions);end
  bias=nan(10,numel(opt.steps));valid=true(limit,numel(opt.steps));
  directional=nan(10,limit,numel(opt.steps));settings=cfg;
  settings.solver.step_tolerance=1e-10;settings.solver.constraint_tolerance=1e-11;
  for h=1:numel(opt.steps)
   step=opt.steps(h);
   for q=1:limit
    yp=d.geometry.y_true+reshape(step*F0(:,q),5,[]);
    ym=d.geometry.y_true-reshape(step*F0(:,q),5,[]);
    rp=jog.solve_camera(yp,F,{truth},settings);rm=jog.solve_camera(ym,F,{truth},settings);
    valid(q,h)=rp.success&&rm.success;
    if valid(q,h),directional(:,q,h)=(jog.Camera.error(rp.camera,truth)+jog.Camera.error(rm.camera,truth))/step^2;end
   end
   if all(valid(:,h)),bias(:,h)=.5*sum(directional(:,:,h),2);end
  end
  rout.hessian=struct('steps',opt.steps,'directional_second_derivative',directional,...
   'b2',bias,'valid',valid,'directions_used',limit,'directions_total',D,...
   'complete_trace',limit==D,'initialization','truth-local branch, diagnostic only','Q_reference','epsilon=1');
 end
 outer={};count=0;
 for bi=1:numel(c.batches)
  b=jog2.Store.read(file,c.batches{bi});
  for k=1:numel(b.trial_id)
   if count>=opt.outer_maps,break;end;count=count+1;
   item=struct('trial_id',b.trial_id(k),'source_valid',b.valid(m,k));
   if ~b.valid(m,k),outer{end+1}=item;continue;end
   y=b.observations(:,:,k);est=jog2.Util.vecCam(b.cameras(:,m,k),truth.scale);
   if ismember('reparameterization',opt.modules)
    settings=cfg;settings.solver.focal_direct=true;
    pool=jog.Camera.initialize(y,cfg);r=jog2.solve_general(y,F,pool,settings);
    item.reparameterization=r;
    item.same_camera_distance=NaN;if ~isempty(r.camera),item.same_camera_distance=norm(jog.Camera.error(r.camera,est)./cfg.solver.parameter_scale);end
    item.cost_difference=r.cost-b.cost(m,k);
   end
   if ismember('profile',opt.modules)
    % One-dimensional gamma_z profile LR evaluated at truth, df=1.
    settings=cfg;settings.solver.free_columns=setdiff(1:10,3);
    pool=jog.Camera.initialize(y,cfg);pool{end+1}=est;
    for z=1:numel(pool),pool{z}.gamma(3)=truth.gamma(3);end
    r=jog2.solve_general(y,F,pool,settings);LR=2*(r.cost-b.cost(m,k));
    item.profile=struct('target','gamma_z','dimension',1,'constrained_fit',r,'LR',LR,...
     'covered95',r.success&&LR>=-1e-7&&LR<=jog.Core.chi2(.95,1),...
     'chi_square_is_approximate',true);
   end
   if ismember('bootstrap',opt.modules)
    C=b.covariance_native(:,:,k,m);L=chol(C,'lower');mu=b.adjusted(:,:,m,k);
    scores=nan(1,opt.inner_maps);fits=cell(1,opt.inner_maps);primitive=zeros(size(F,2),opt.inner_maps);substreams=zeros(1,opt.inner_maps);observations=zeros(size(mu,1),size(mu,2),opt.inner_maps);
    for inner=1:opt.inner_maps
     assert(count<=5000,'Split advanced runs above 5000 outer maps');
     gid=(ii-1)*50+floor((count-1)/100);coupling=mod(count-1,100);
     [rs,sid]=jog2.Util.stream(cfg,16,gid,coupling,inner,4);
     zz=randn(rs,size(F,2),1);primitive(:,inner)=zz;substreams(inner)=sid;
     yy=mu+reshape(F*zz,5,[]);observations(:,:,inner)=yy;
     pool=jog.Camera.initialize(yy,cfg);r=jog.solve_camera(yy,F,pool,cfg);r.bootstrap_substream=sid;
     fits{inner}=r;if r.success,e=jog.Camera.error(r.camera,est);scores(inner)=sum((L\e).^2);end
    end
    threshold=jog.Core.quantile(scores,.95);err=-b.errors(:,k,m);actual=sum((L\err).^2);
    item.bootstrap=struct('scores',scores,'threshold95',threshold,'fits',{fits},...
     'observations',observations,'primitive_normals',primitive,'substreams',substreams,'covered95',actual<=threshold,'valid_count',nnz(isfinite(scores)),...
     'region','bootstrap-calibrated fixed-outer-covariance Wald','outer_nees',actual);
   end
   var=sprintf('%s_J16g%02do%04d',o.meta.run_id,ii,count);payload=struct();payload.(var)=item;
   o.extra_datasets{end+1}=jog2.Archive.putValue(file,var,item,'advanced');
   outer{end+1}=struct('variable',var,'trial_id',item.trial_id,'source_valid',item.source_valid);
  end
  if count>=opt.outer_maps,break;end
 end
 rout.outer=outer;result.conditions{end+1}=rout;
end
% Optional experiments can be large: separate top-level variable, same MAT.
prefix=[o.meta.run_id '_J16'];o.extra_datasets{end+1}=jog2.Archive.putValue(file,prefix,result,'advanced');
o.diagnostics.J16=struct('variable',prefix,'modules',{opt.modules},'status','complete');
jog2.Store.saveMetadata(file,o);
end

function outputFile=jog_analyze_v2(input,diagnostics,varargin)
% Resumable condition analysis. Never restarts camera fitting.
if nargin<2,diagnostics={'D01','D02','D03','D04','J15'};end
p=inputParser;addParameter(p,'MaxConditions',Inf);parse(p,varargin{:});
if isstruct(input),input=input.output_file;end
if isfolder(input),input=fullfile(input,'output.mat');end
outputFile=input;o=jog2.Store.metadata(input);
assert(jog2.Archive.isArchive(input),'Run jog_recover_v2 on the old checkpoint folder first');
assert(o.meta.complete,'Raw archive is incomplete');
cfg=o.config;started=tic;done=0;
folder=fullfile(fileparts(input),'analysis_checkpoints');if ~exist(folder,'dir'),mkdir(folder);end
sourceHash=jog2.Util.hash(jsonencode(jog2.Util.sources()));
token=jog2.Util.hash([o.meta.pack_identity sourceHash jsonencode(diagnostics)]);
o.meta.analysis_complete=false;o.meta.status='analyzing';jog2.Store.saveMetadata(input,o);
o.summaries=cell(size(o.conditions));
for i=1:numel(o.conditions)
 c=o.conditions{i};cache=fullfile(folder,[c.prefix '_summary.mat']);
 if exist(cache,'file')
  previous=load(cache,'record');rr=previous.record;
  if strcmp(rr.token,token)&&strcmp(rr.prefix,c.prefix)
   o.summaries{i}=rr.summary;o.conditions{i}=rr.condition;
   fprintf('Analyze %s %d/%d | cached complete\n',c.suite,i,numel(o.conditions));continue;
  end
 end
 fprintf('Analyze %s %d/%d | statistics\n',c.suite,i,numel(o.conditions));one=tic;
 s=jog2.Analysis.condition(input,c,cfg);
 if ismember('J15',diagnostics)&&ismember('J15',cfg.enabled)&&ismember(c.suite,cfg.j15.source_suites)
  d=jog2.Store.design(input,c);targets=cell(size(c.batches));target_entries=cell(size(c.batches));
  for j=1:numel(c.batches)
   prefix=[c.batches{j}.prefix '_target'];probe=struct('prefix',prefix);
   if jog2.Archive.ready(input,probe,token)
    e=jog2.Archive.entry(input,prefix,'batch');t=jog2.Store.read(input,e);
   else
    b=jog2.Store.read(input,c.batches{j});t=jog2.Target.batch(b,d,cfg);
    e=jog2.Archive.putValue(input,prefix,t,'batch',token);
   end
   targets{j}=t;target_entries{j}=e;
   if mod(j,10)==0||j==numel(c.batches),fprintf('  J15 batch %d/%d | %.1f s\n',j,numel(c.batches),toc(one));end
  end
  c.target_batches=target_entries;s.targets=jog2.Target.summarize(targets,d,cfg);clear targets;
 end
 o.conditions{i}=c;o.summaries{i}=s;
 record=struct('token',token,'prefix',c.prefix,'summary',s,'condition',c,'completed_utc',jog2.Util.utc(),'seconds',toc(one));
 jog2.Util.saveAtomic(cache,'record',record);done=done+1;
 fprintf('Analyze %s %d/%d | saved complete, %.1f s\n',c.suite,i,numel(o.conditions),toc(one));
 if done>=p.Results.MaxConditions,fprintf('Analysis paused after completed condition; call jog_analyze_v2 again to resume.\n');return;end
end
o.diagnostics.geometry_population=jog2.Analysis.population(o);
if isfield(o.legacy,'J04')
 x=jog2.Store.read(input,o.legacy.J04);vf=cell(size(x.conditions));
 for ci=1:numel(x.conditions)
  cc=x.conditions{ci};values=cc.residual_energy/2;
  rejected=cc.residual_energy<jog.Core.chi2(.025,2)|cc.residual_energy>jog.Core.chi2(.975,2);
  vf{ci}=struct('tau',cc.tau,'values',values,'df',2,'mean',mean(values),...
   'rejection_rate',mean(rejected),'wilson',jog.Core.wilson(sum(rejected),numel(values)),...
   'reference','exact linear Gaussian, sigma0_squared=1');
 end
 o.diagnostics.J04_variance_factor=vf;
end
slopes={};sel=find(cellfun(@(c)strcmp(c.suite,'J10'),o.conditions));
if ~isempty(sel)
 gids=unique(cellfun(@(c)c.spec.geometry_id,o.conditions(sel)));
 for gid=gids
  ix=sel(cellfun(@(c)c.spec.geometry_id==gid&&ismember(c.spec.noise_scale,[.03 .1 .3]),o.conditions(sel)));
  if numel(ix)<3,continue;end
  xs=[];ys=[];invalid=[];
  for ci=ix
   mm=find(strcmp(o.summaries{ci}.methods,'GH_FULL'),1);if isempty(mm),continue;end
   a=o.summaries{ci}.method{mm};xs(end+1)=o.summaries{ci}.spec.noise_scale;
   ys(end+1)=a.remainder.normalized_rms;invalid(end+1)=a.n_total-a.n_valid;
  end
  ok=isfinite(ys)&ys>0;
  if nnz(ok)>=3,coef=polyfit(log(xs(ok)),log(ys(ok)),1);else,coef=[NaN NaN];end
  slopes{end+1}=struct('geometry_id',gid,'epsilon',xs,'rho',ys,'fit',coef,...
   'invalid_counts',invalid,'interpretation','diagnostic conditional slope; not an acceptance threshold');
 end
end
o.diagnostics.J10_small_noise_slopes=slopes;

o.diagnostics.completed=diagnostics;o.diagnostics.created_utc=jog2.Util.utc();
o.diagnostics.definition='D01 valid-fit bias/NEES/branches; D02 absolute-scale diagnostic; D03 metric-declared blocks; D04 true design';
o.meta.analysis_source_code=jog2.Util.sources();o.meta.analysis_source_hash=jog2.Util.hash(jsonencode(o.meta.analysis_source_code));
o.meta.analysis_complete=true;o.meta.status='analysis_complete';
o.meta.analysis_token=token;o.meta.analysis_seconds=toc(started);
jog2.Store.saveMetadata(input,o);
jog2.Export.tables(input);
end

function report=jog_check_output(filename)
%JOG_CHECK_OUTPUT Validate saved data and print a concise summary.
x=load(filename,'output');o=x.output;assert(strcmp(o.schema_version,'jog-output-1.0'));
assert(o.selftest.passed);ids=o.progress.completed_ids;
for i=1:numel(o.config.enabled),assert(ismember(o.config.enabled{i},ids),'Incomplete experiment.');end
report=struct('profile',o.config.profile,'status',o.meta.status,'experiments',{ids},...
 'figure_count',numel(o.figure_manifest),'nonlinear_counts',[]);
if isfield(o.experiments,'J09')
 cs=o.experiments.J09.conditions;rows={};
 for c=1:numel(cs)
  r=cs{c};assert(size(r.observations,3)==o.config.mc_nonlinear);
  assert(size(r.runs,2)==o.config.mc_nonlinear);
  for m=1:numel(r.methods)
   s=r.summary{m};assert(s.n_total==o.config.mc_nonlinear);
   assert(s.position.n_total==o.config.mc_nonlinear);
   rows(end+1,:)={c,r.spec.sweep,r.spec.x,r.methods{m},s.n_valid,s.n_total,s.failure_rate}; %#ok<AGROW>
  end
 end
 report.nonlinear_counts=cell2table(rows,'VariableNames',{'condition','sweep','x','method','valid','total','failure_rate'});
 disp(report.nonlinear_counts);
end
fprintf('Profile=%s, status=%s, experiments=%d, PNG figures=%d\n',report.profile,report.status,numel(ids),report.figure_count);
end

function report=jog_check_output_v2(file,mode)
if nargin<2,mode='strict';end
o=jog2.Store.metadata(file);assert(strcmp(o.schema_version,'jog-output-2.1'));
assert(o.meta.complete,'Partial run is not a finished output');
assert(jog2.Archive.isArchive(file));entries=jog2.Store.entries(o);
for k=1:numel(entries),assert(jog2.Archive.ready(file,entries{k}),'Missing/incomplete payload');end
report=struct('passed',true,'conditions',numel(o.conditions),'maps',0,'fits',0,...
 'successful_fits',0,'observation_reconstruction_error',0,'max_valid_closure',0,'covariance_asymmetry',0,...
 'data_self_contained',true,'checked_utc',jog2.Util.utc(),'mode',mode);
for i=1:numel(o.conditions)
 c=o.conditions{i};d=jog2.Store.design(file,c);ids=[];
 fprintf('Integrity %s %d/%d\n',c.suite,i,numel(o.conditions));
 for j=1:numel(c.batches)
  b=jog2.Store.read(file,c.batches{j});ids=[ids b.trial_id];
  y=d.geometry.y_true+reshape(b.eta,5,d.spec.n,[]);
  er=max(abs(y(:)-b.observations(:)));report.observation_reconstruction_error=max(report.observation_reconstruction_error,er);
  assert(er<1e-10,'Observation data mismatch');
  report.maps=report.maps+numel(b.trial_id);report.fits=report.fits+numel(b.valid);
  report.successful_fits=report.successful_fits+nnz(b.valid);
  if any(b.valid(:)),report.max_valid_closure=max(report.max_valid_closure,max(b.closure(b.valid)));end
  for m=1:numel(d.methods)
   for k=find(b.valid(m,:))
    C=b.covariance_native(:,:,k,m);[~,flag]=chol((C+C')/2);assert(flag==0&&all(isfinite(C(:))),'Invalid covariance flagged valid');
    report.covariance_asymmetry=max(report.covariance_asymmetry,norm(C-C','fro')/max(1,norm(C,'fro')));
   end
  end
 end
 assert(isequal(sort(ids),1:c.spec.N)&&numel(unique(ids))==numel(ids),'Missing or duplicate trials');
end
report.map_count_definition='condition-map evaluations; paired scales/geometries are correlated across conditions';
o.validation.integrity=report;report.root_link_count=jog2.Archive.rootCount(file);o.validation.integrity=report;jog2.Store.saveMetadata(file,o);
log=fullfile(fileparts(file),'integrity.json');f=fopen(log,'w');cl=onCleanup(@()fclose(f));fprintf(f,'%s',jsonencode(report,PrettyPrint=true));
fprintf('Integrity OK: %d condition-map evaluations, %d fits, %d valid\n',report.maps,report.fits,report.successful_fits);
end

function cfg = jog_config(profile)
%JOG_CONFIG Reproducible simulation settings; base MATLAB only.
% Profiles have different seeds. Paper is a proposed final configuration,
% not an assertion that the results are ready for publication.
if nargin==0, profile='pilot'; end
cfg.schema_version='jog-output-1.0';
cfg.profile=char(profile); cfg.enabled={'J00','J01','J02','J03','J04','J05','J06','J07','J08','J09'};
cfg.master_seed=1009162026;
cfg.mc_linear=1000; cfg.mc_plane=1000; cfg.mc_nonlinear=100;
cfg.identity_cases=50;
cfg.nominal=[.50 .80 .90 .95 .99];
cfg.fig_dpi=300; cfg.figure_visible='off';
cfg.save_candidate_history=true;
cfg.linear.s=[10 30 100 300 1000 3000 10000];
cfg.linear.rho=[0 .3 .6 .9]; cfg.linear.tau=[0 .1 .3 1 3 10];
cfg.linear.rates=[.25 .5 .75];
cfg.plane.f=3500; cfg.plane.gamma_z=1.5; cfg.plane.depths=[10 15 20 25];
cfg.plane.n=[4 10 30 100 300 1000];
cfg.plane.region_std=[.02 .10]; cfg.plane.image_std=.5;
cfg.plane.local_depth_std=.02; cfg.plane.horizontal_radius=1.5;
cfg.plane.group_counts=[2 4 8 16];
cfg.plane.depth_spreads=[.02 .05 .10 .20 .40 .60];
cfg.plane.global_stds=[0 .01 .03 .06 .10];
cfg.plane.guard_lambda=[1 10000]; cfg.plane.guard_min_information=1e-8;
cfg.plane.fallback=[0;3000];
cfg.camera.width=6000; cfg.camera.height=4000; cfg.camera.scale=3000;
cfg.camera.gamma=[2;-1;1.5]; cfg.camera.rotvec=[.15;-.10;.05];
cfg.camera.f=3500; cfg.camera.pp=[25;-15]; cfg.camera.kappa=-.08;
cfg.camera.mean_depth=20; cfg.camera.occupancy=.75;
cfg.camera.local_image_std=.5; cfg.camera.local_xyz_std=.02;
cfg.camera.patch_std=.02; cfg.camera.global_std=.05;
cfg.camera.anisotropy=1;
cfg.nonlinear.noise_scales=[.1 .3 1 2];
cfg.nonlinear.depth_spreads=[.02 .05 .15 .30];
cfg.nonlinear.point_counts=[13 30 60];
cfg.nonlinear.baseline_points=30; cfg.nonlinear.baseline_spread=.15;
cfg.nonlinear.methods={'FIXED3D_WLS','GH_LOCAL','GH_MARGDIAG','GH_FULL'};
cfg.nonlinear.initialization='observed_DLT_multistart';
% The separate oracle diagnostic mode may be selected explicitly. It is
% labeled in output and is never mixed with practical end-to-end results.
cfg.nonlinear.kappa_initial=[-.15 0 .15];
cfg.solver.max_iterations=100; cfg.solver.max_linesearch=18;
cfg.solver.step_tolerance=2e-8; cfg.solver.constraint_tolerance=2e-9;
cfg.solver.rank_tolerance=1e-10;
