function file=jog_realdata_v2(data,cfg,destination)
%JOG_REALDATA_V2 Optional R01 adapter: measured y + externally supplied Q.
% data.y: 5xn [u;v;X;Y;Z], centered pixels/metres.
% data.Q_local, data.G_raw, data.Q_b, data.covariance_provenance required.
% No empirical camera coverage is inferred from a single real map.
required={'y','Q_local','G_raw','Q_b','covariance_provenance'};
for k=1:numel(required),assert(isfield(data,required{k}),'Missing real-data field %s',required{k});end
assert(size(data.y,1)==5&&size(data.y,2)>=6);
no=struct('Q_local',data.Q_local,'G_raw',data.G_raw,'Q_b',data.Q_b);
no.F_local=jog2.Util.psdfactor(no.Q_local);no.F_common=no.G_raw*jog2.Util.psdfactor(no.Q_b);
no.Q_full=no.Q_local+no.F_common*no.F_common';
pool=jog.Camera.initialize(data.y,cfg);fits=cell(size(cfg.nonlinear.methods));
for m=1:numel(fits),F=jog.Camera.factor(no,cfg.nonlinear.methods{m});fits{m}=jog.solve_camera(data.y,F,pool,cfg);end
if ~exist(destination,'dir'),mkdir(destination);end
output=struct('schema_version','jog-real-2.0','config',cfg,'data',data,'noise_model',no,...
 'methods',{cfg.nonlinear.methods},'initializers',{pool},'fits',{fits},...
 'meta',struct('dataset_type','real_single_map','created_utc',jog2.Util.utc(),...
 'source_code',jog2.Util.sources(),'coverage_claim','not estimated from one map',...
 'complete',true,'covariance_source',data.covariance_provenance));
file=fullfile(destination,'output.mat');assert(~exist(file,'file'),'Destination exists');save(file,'output','-v7.3');
end

function file=jog_recover_v2(source,destination,varargin)
% Recover completed raw simulations from v2.0 or v2.1 checkpoints.
% NEVER modifies source files and NEVER invokes a camera solver.
p=inputParser;addParameter(p,'Analyze',true);addParameter(p,'MakeFigures',true);
addParameter(p,'SourceRuns',[]);addParameter(p,'CheckIntegrity',true);addParameter(p,'MaxPackEntries',Inf);parse(p,varargin{:});
if isfolder(source),checkpoint=fullfile(source,'checkpoint.mat');
elseif endsWith(source,'checkpoint.mat'),checkpoint=source;
else,checkpoint=fullfile(fileparts(source),'checkpoint.mat');end
assert(exist(checkpoint,'file')==2,'checkpoint.mat and checkpoints/ are required. Select the original run folder.');
if nargin<2||isempty(destination)
 destination=fullfile(pwd,'results',['recovered_' datestr(now,'yyyymmdd_HHMMSS')]);
end
original=jog2.Store.metadata(checkpoint);jog2.Store.assertRawComplete(original);
fprintf('Recover raw run %s | %d conditions | no simulation will run\n',original.meta.run_id,numel(original.conditions));
% Old source-run merging requires separate conversion; never silently omit it.
sources=original.config.source_runs;
if ~isempty(p.Results.SourceRuns)
 assert(iscell(p.Results.SourceRuns)&&numel(p.Results.SourceRuns)==numel(sources),'Provide one converted archive for every original source run');
 sources=p.Results.SourceRuns;
end
for k=1:numel(sources),assert(jog2.Archive.isArchive(sources{k}),'Convert each old source run separately before merged recovery');end
file=jog2.Store.packCheckpoint(checkpoint,destination,sources,p.Results.MaxPackEntries);
if endsWith(file,'output.packing.mat'),return;end
if p.Results.Analyze,jog_analyze_v2(file);end
if p.Results.MakeFigures
 o=jog2.Store.metadata(file);assert(isfield(o.meta,'analysis_complete')&&o.meta.analysis_complete,'Complete analysis before rendering');
 jog_make_figures_v2(file,'paper');
end
if p.Results.CheckIntegrity,jog_check_output_v2(file);end
fprintf('Recovered: %s\n',file);
end

function report=jog_selftest(cfg)
%JOG_SELFTEST Fast prerequisites: algebra, Jacobians, guard and initializer.
if nargin==0,cfg=jog_config('smoke');end
rng(cfg.master_seed,'twister');g=jog.Camera.geometry(cfg,30,.3,cfg.master_seed);
c=g.truth_camera;y=g.y_true;[psi,A,B,ok]=jog.Camera.evaluate(y,c);
assert(ok && norm(psi,inf)<1e-12,'Noiseless projection failed.');
An=zeros(size(A));Bn=zeros(size(B));
for j=1:10
 h=1e-5;if j==7||j==8||ismember(j,4:6),h=1e-6;end
 dx=zeros(10,1);dx(j)=h;
 pp=jog.Camera.evaluate(y,jog.Camera.step(c,dx));pm=jog.Camera.evaluate(y,jog.Camera.step(c,-dx));
 An(:,j)=-(pp-pm)/(2*h);
end
for j=1:numel(y)
 h=1e-5;if mod(j-1,5)<2,h=1e-4;end
 yp=y;ym=y;yp(j)=yp(j)+h;ym(j)=ym(j)-h;
 Bn(:,j)=(jog.Camera.evaluate(yp,c)-jog.Camera.evaluate(ym,c))/(2*h);
end
errA=max(abs(A(:)-An(:)));errB=max(abs(B(:)-Bn(:)));
assert(errA<1e-7 && errB<1e-7,'Camera Jacobian check failed.');
no=jog.Camera.noiseModel(cfg,g,1,'global');L=chol(B*no.Q_local*B','lower');
d=jog.Core.linear(L\A,L\(B*no.G_raw),no.Q_b);
assert(jog.Core.relative(d.Sigma,d.Sigma_direct)<1e-7);
assert(jog.Core.relative(d.W,d.W_direct)<1e-7);
% Local truth-initialized zero-noise run checks adjustment, not practical initialization.
fit=jog.solve_camera(y,jog.Camera.factor(no,'GH_FULL'),{c},cfg);
assert(fit.success && norm(jog.Camera.error(fit.camera,c))<1e-8,'Noiseless GHM failed.');
pool=jog.Camera.initialize(y,cfg);assert(~isempty(pool),'Observed DLT produced no initializer.');
practical=jog.solve_camera(y,jog.Camera.factor(no,'GH_FULL'),pool,cfg);
assert(practical.success,'Observed DLT + noiseless adjustment failed.');
assert(norm(jog.Camera.error(practical.camera,c))<1e-4,'Noiseless parameter recovery failed.');
% Force the plane guard to fail: finite fallback moments, no spurious coverage.
probe=cfg;probe.mc_plane=2;probe.plane.global_stds=0;probe.plane.guard_lambda=[.01 .1];
guardTest=jog.plane_suite('J08',probe);gs=guardTest.conditions{1};
assert(~any(gs.guard_accepted) && gs.summary_all_including_fallback.n_valid==2);
assert(gs.summary_all_including_fallback.n_covariance_valid==0);
assert(all(gs.summary_all_including_fallback.coverage_operational==0));
assert(gs.summary_known_f.n_covariance_valid==0,'Fallback issued a confidence region.');
report=struct('passed',true,'guard_failure_bookkeeping_passed',true,'max_A_difference',errA,'max_B_difference',errB,...
 'GLS_covariance_relative_difference',jog.Core.relative(d.Sigma,d.Sigma_direct),...
 'observed_initializer_count',numel(pool),'noiseless_parameter_error',norm(jog.Camera.error(practical.camera,c)),...
 'note','Deterministic prerequisites only; production Monte Carlo is separate.');
disp(report);
end

function report=jog_selftest_v2(cfg)
if nargin==0,cfg=jog_config_v2('smoke');end
report.legacy=jog_selftest(cfg);
g=jog2.Geometry.paired(cfg,30,.15,13,1);
s=jog2.Noise.spec(cfg,'similarity');s.pivot=mean(g.master_xyz,2);
s.rotation_std=.005*pi/180;s.translation_std=.02;s.scale_std=20e-6;
no=jog2.Noise.build(g,s);[~,A,B]=jog.Camera.evaluate(g.y_true,g.truth_camera);
rr=g.truth_camera.gamma-s.pivot;T=zeros(10,7);T(1:3,:)=[-jog.Camera.skew(rr),eye(3),rr];T(4:6,1:3)=-g.truth_camera.R;
report.similarity_loading=jog.Core.relative(A*T,B*no.G_raw);
shift=[20;0;0];M=eye(7);M(4:6,1:3)=-jog.Camera.skew(shift);M(4:6,7)=shift;
s.pivot=s.pivot+shift;s.Qb_override=M*no.Q_b*M';no2=jog2.Noise.build(g,s);
report.pivot=jog.Core.relative(no.Q_full,no2.Q_full);
F=jog.Camera.factor(no,'GH_FULL');ref=jog2.Noise.reference(g,no,F,cfg);
report.nominal_sandwich=jog.Core.relative(ref.nominal_covariance,ref.actual_sampling_covariance);
s=jog2.Noise.spec(cfg,'patch');tr=jog2.Noise.build(g,s);s.alpha=4;as=jog2.Noise.build(g,s);
ref=jog2.Noise.reference(g,tr,jog.Camera.factor(as,'GH_FULL'),cfg);
e=eig((ref.nominal_covariance-ref.actual_sampling_covariance+ref.nominal_covariance'-ref.actual_sampling_covariance')/2);
report.inflation_min_eigenvalue=min(e);
s=jog2.Noise.spec(cfg,'patch_global');s.patch_std=0;s.global_std=0;no=jog2.Noise.build(g,s);
report.zero_psd_factor=size(no.L_b,2);assert(isempty(no.L_b));
[r,a]=jog2.Util.stream(cfg,12,1,0,1,1);v=randn(r,20,1);
[r,b]=jog2.Util.stream(cfg,12,1,0,1,1);assert(isequal(v,randn(r,20,1))&&a==b);
assert(report.similarity_loading<1e-9&&report.pivot<1e-10&&report.nominal_sandwich<1e-8);
assert(report.inflation_min_eigenvalue>-1e-7);
t=jog2.Target.design(g,cfg);report.target_step_halving=struct();
for kind={'plane','image'}
 [~,J1]=jog2.Target.values(g.truth_camera,t,kind{1},1);[~,J2]=jog2.Target.values(g.truth_camera,t,kind{1},.5);
 discrepancy=jog.Core.relative(J1(:),J2(:));report.target_step_halving.(kind{1})=discrepancy;
 assert(discrepancy<1e-5,'Target numerical derivative failed step-halving');
end
report.passed=true;
end

