classdef Camera
methods(Static)
 function S=skew(x)
  S=[0 -x(3) x(2);x(3) 0 -x(1);-x(2) x(1) 0];
 end
 function R=exp(v)
  t=norm(v);K=jog.Camera.skew(v);
  if t<1e-8,R=eye(3)+K+.5*K*K;else,R=eye(3)+sin(t)/t*K+(1-cos(t))/t^2*K*K;end
 end
 function v=log(R)
  c=max(-1,min(1,(trace(R)-1)/2));t=acos(c);
  a=[R(3,2)-R(2,3);R(1,3)-R(3,1);R(2,1)-R(1,2)];
  if t<1e-7,v=.5*a;
  elseif pi-t<1e-5
   [V,D]=eig((R+R')/2);[~,i]=max(diag(D));v=t*V(:,i);if dot(v,a)<0,v=-v;end
  else,v=t/(2*sin(t))*a;end
 end
 function J=leftInverse(v)
  t=norm(v);K=jog.Camera.skew(v);
  if t<1e-5,J=eye(3)-.5*K+K*K/12;
  else,J=eye(3)-.5*K+(1/t^2-(1+cos(t))/(2*t*sin(t)))*K*K;end
 end
 function c=truth(cfg)
  x=cfg.camera;c=struct('gamma',x.gamma,'R',jog.Camera.exp(x.rotvec),...
   'phi',log(x.f/x.scale),'kappa',x.kappa,'pp',x.pp,'scale',x.scale);
 end
 function c=step(c,delta)
  c.gamma=c.gamma+delta(1:3);c.R=jog.Camera.exp(delta(4:6))*c.R;
  c.phi=c.phi+delta(7);c.kappa=c.kappa+delta(8);c.pp=c.pp+delta(9:10);
 end
 function [psi,A,B,physical,reason]=evaluate(y,c)
  n=size(y,2);psi=zeros(2*n,1);A=zeros(2*n,10);B=zeros(2*n,5*n);
  physical=true;reason='';ff=exp(c.phi);
  for i=1:n
   d=(y(1:2,i)-c.pp)/c.scale;rr=d'*d;h=1+c.kappa*rr;
   t=c.R*(y(3:5,i)-c.gamma);ii=2*i-1:2*i;jj=5*i-4:5*i;
   if t(3)<=1e-6,physical=false;reason='negative_depth';return;end
   if h<=1e-5 || 1-c.kappa*rr<=1e-5,physical=false;reason='distortion_not_invertible';return;end
   g=t(1:2)/t(3);E=eye(2)/h-2*c.kappa/h^2*(d*d');
   P=[1 0 -g(1);0 1 -g(2)]/t(3);
   psi(ii)=d/h-ff*g;
   A(ii,:)=[-ff*P*c.R,-ff*P*jog.Camera.skew(t),ff*g,rr*d/h^2,E/c.scale];
   B(ii,jj)=[E/c.scale,-ff*P*c.R];
  end
 end
 function uv=project(x,c)
  t=c.R*(x-c.gamma);a=exp(c.phi)*t(1:2,:)./t(3,:);
  disc=1-4*c.kappa*sum(a.^2,1);uv=nan(size(a));good=t(3,:)>0 & disc>0;
  lam=2./(1+sqrt(disc(good)));uv(:,good)=c.pp+c.scale*a(:,good).*lam;
 end
 function geom=geometry(cfg,n,spread,seed)
  rng(seed,'twister');c=jog.Camera.truth(cfg);x=cfg.camera;
  patch=mod(0:n-1,4)+1;signs=[-1 1 -1 1;-1 -1 1 1];
  uv=zeros(2,n);
  for i=1:n
   uv(:,i)=signs(:,patch(i)).*(.12+.88*rand(2,1)).*[x.width;x.height]*x.occupancy/2;
  end
  % Exactly fixed geometry within independent noise/map repeats.
  z=x.mean_depth*(1+spread*(rand(1,n)-.5));
  d=(uv-c.pp)/x.scale;a=d./(1+c.kappa*sum(d.^2,1));
  t=[a/exp(c.phi).*z;z];xyz=c.gamma+c.R'*t;
  geom=struct('truth_camera',c,'y_true',[uv;xyz],'patch_id',patch,...
   'point_id',1:n,'seed',seed,'spread_requested',spread,...
   'depth_actual',z,'depth_cv',std(z,1)/mean(z),...
   'image_hull_fraction',polyarea(uv(1,convhull(uv(1,:),uv(2,:))),uv(2,convhull(uv(1,:),uv(2,:))))/(x.width*x.height));
 end
 function noise=noiseModel(cfg,geom,scale,kind)
  assert(any(strcmp(kind,{'patch','global'})),'Unknown legacy noise kind');
  n=size(geom.y_true,2);x=cfg.camera;
  Ql=zeros(5*n);ratio=x.anisotropy;
  xyzvar=x.local_xyz_std^2*diag([3/(2+ratio^2),3/(2+ratio^2),3*ratio^2/(2+ratio^2)]);
  for i=1:n,jj=5*i-4:5*i;Ql(jj,jj)=blkdiag(x.local_image_std^2*eye(2),xyzvar)*scale^2;end
  if strcmp(kind,'global'),G=zeros(5*n,3);qb=x.global_std^2*scale^2*eye(3);
  else,G=zeros(5*n,12);qb=x.patch_std^2*scale^2*eye(12);end
  for i=1:n
   rr=5*i-2:5*i;if strcmp(kind,'global'),cc=1:3;else,cc=3*geom.patch_id(i)-2:3*geom.patch_id(i);end
   G(rr,cc)=eye(3);
  end
  Qfull=Ql+G*qb*G';F_local=chol(Ql,'lower');Fcommon=G*chol(qb,'lower');
  noise=struct('Q_local',Ql,'G_raw',G,'Q_b',qb,'F_local',F_local,...
   'F_common',Fcommon,'Q_full',Qfull,'kind',kind,'noise_scale',scale);
 end
 function F=factor(noise,method)
  n=size(noise.Q_local,1)/5;
  switch method
   case 'GH_FULL',F=[noise.F_local,noise.F_common];
   case 'GH_LOCAL',F=noise.F_local;
   case 'GH_MARGDIAG'
    F=zeros(5*n);for i=1:n,j=5*i-4:5*i;F(j,j)=chol(noise.Q_full(j,j),'lower');end
   case 'FIXED3D_WLS'
    F=zeros(5*n,2*n);for i=1:n,j=5*i-4:5*i-3;F(j,2*i-1:2*i)=chol(noise.Q_local(j,j),'lower');end
   otherwise,error('Unknown method');
  end
 end
 function pool=initialize(y,cfg)
  % Uses observed points only; no pose/IOP truth is passed to this routine.
  pool={};sc=cfg.camera.scale;n=size(y,2);x=y(3:5,:);
  centre=mean(x,2);sx=sqrt(mean(sum((x-centre).^2,1))/3);
  if sx<=eps,return;end
  xn=(x-centre)/sx;X=[xn;ones(1,n)];Tw=[eye(3)/sx,-centre/sx;0 0 0 1];
  for kap=cfg.nonlinear.kappa_initial
   dd=y(1:2,:)/sc;uu=dd./(1+kap*sum(dd.^2,1));
   D=zeros(2*n,12);
   for i=1:n
    D(2*i-1,:)=[X(:,i)' zeros(1,4) -uu(1,i)*X(:,i)'];
    D(2*i,:)=[zeros(1,4) X(:,i)' -uu(2,i)*X(:,i)'];
   end
   [~,S,V]=svd(D,0);if S(end-1,end-1)<1e-10*S(1,1),continue;end
   P=reshape(V(:,end),4,3)'*Tw;M=P(:,1:3);
   if rcond(M)<1e-12,continue;end
   if det(M)<0,P=-P;M=-M;end
   [Q,R]=qr(flipud(M)');K=fliplr(flipud(R'));Rc=flipud(Q');
   sg=sign(diag(K));sg(sg==0)=1;Ds=diag(sg);K=K*Ds;Rc=Ds*Rc;
   K=K/K(3,3);f=sc*mean([K(1,1),K(2,2)]);
   if f<=cfg.solver.focal_range(1)||f>=cfg.solver.focal_range(2)||det(Rc)<0,continue;end
   c=struct('gamma',-M\P(:,4),'R',Rc,'phi',log(f/sc),'kappa',kap,'pp',sc*K(1:2,3),'scale',sc);
   if any(abs(c.pp)>cfg.solver.principal_point_absmax),continue;end
   [~,~,~,ok]=jog.Camera.evaluate(y,c);if ok,pool{end+1}=c;end %#ok<AGROW>
  end
 end
 function e=error(c,truth)
  e=[c.gamma-truth.gamma;jog.Camera.log(c.R*truth.R');c.phi-truth.phi;c.kappa-truth.kappa;c.pp-truth.pp];
 end
end
end

classdef Core
methods(Static)
 function s=seed(cfg,suite,condition,trial)
  s=cfg.master_seed+suite*10000000+condition*10000+trial;
  assert(s<2^32 && trial<10000,'Seed range exceeded.');
 end
 function [Ni,H,rankA,condition]=normal(A,tol)
  if nargin<2,tol=1e-10;end
  scale=sqrt(sum(A.^2,1));
  if any(scale==0),error('jog:rank_deficient','Zero design column.');end
  An=A./scale; sv=svd(An,'econ'); rankA=sum(sv>tol*sv(1));
  condition=sv(1)/sv(end);
  if rankA<size(A,2),error('jog:rank_deficient','Scaled design rank deficient.');end
  Nn=An'*An; R=chol((Nn+Nn')/2);
  Ci=R\(R'\eye(size(Nn))); D=diag(1./scale);
  Ni=D*Ci*D; Ni=(Ni+Ni')/2; H=An*Ci*An'; H=(H+H')/2;
 end
 function d=linear(A,U,Qb)
  [Ni,H,ra,ca]=jog.Core.normal(A);
  T=Ni*A'*U; V=U-A*T; J=V'*V;
  if isempty(U)
   Pb=zeros(0); K=zeros(0); Omega=eye(size(A,1));
  else
   qi=Qb\eye(size(Qb)); Pb=(qi+J)\eye(size(Qb)); Pb=(Pb+Pb')/2;
   C=chol(Qb,'lower'); K=C'*J*C; Omega=eye(size(A,1))+U*Qb*U';
  end
  W=Ni*A'-T*Pb*V'; Sigma=Ni+T*Pb*T'; Sigma=(Sigma+Sigma')/2;
  Lo=chol((Omega+Omega')/2,'lower'); Ao=Lo\A;
  [direct,~,~,~]=jog.Core.normal(Ao); Wdirect=direct*Ao'/Lo;
  d=struct('A',A,'U',U,'Qb',Qb,'N_local',A'*A,'N_full',Ao'*Ao,...
   'N_local_inverse',Ni,'H',H,'T',T,'V',V,'J',J,'Q_b_given_r',Pb,...
   'K',K,'learning_spectrum',sort(max(0,eig((K+K')/2)),'descend'),...
   'Sigma',Sigma,'Sigma_direct',direct,'W',W,'W_direct',Wdirect,...
   'Omega',Omega,'rank_A',ra,'condition_A_scaled',ca);
 end
 function [v,spectrum]=inflation(d,L)
  c0=L*d.N_local_inverse*L'; dc=L*d.T*d.Q_b_given_r*d.T'*L';
  C=chol((c0+c0')/2,'lower'); M=C\dc/C';
  spectrum=1+sort(max(0,eig((M+M')/2)),'descend');v=max(spectrum);
 end
 function e=relative(A,B)
  e=norm(A-B,'fro')/max([1,norm(A,'fro'),norm(B,'fro')]);
 end
 function x=chi2(p,df)
  x=2*gammaincinv(p,df/2);
 end
 function ci=wilson(k,n)
  if n==0,ci=[NaN NaN];return;end
  z=1.95996398454005; ph=k/n; den=1+z*z/n;
  mid=(ph+z*z/(2*n))/den;
  half=z*sqrt(ph*(1-ph)/n+z*z/(4*n*n))/den; ci=[mid-half mid+half];
 end
 function s=summarize(errors,covariances,valid,nominal)
  % Columns are independent map realizations. Failures remain in total N.
  [p,N]=size(errors); ix=find(valid & all(isfinite(errors),1)); nv=numel(ix);
  s=struct('n_total',N,'n_valid',nv,'failure_rate',1-nv/N,...
   'bias',nan(p,1),'covariance',nan(p),'std',nan(p,1),'std_ci',nan(p,2),...
   'rmse',NaN,'mean_predicted_covariance',nan(p),'predicted_std',nan(p,1),...
   'nominal',nominal,'coverage_conditional',nan(size(nominal)),...
   'coverage_operational',zeros(size(nominal)),'coverage_wilson',nan(numel(nominal),2),...
   'nees',nan(1,N),'n_covariance_valid',0);
  if nv==0,return;end
  X=errors(:,ix); s.bias=mean(X,2); s.rmse=sqrt(mean(sum(X.^2,1)));
  if nv>=2
   xc=X-s.bias; s.covariance=xc*xc'/(nv-1); s.std=sqrt(max(0,diag(s.covariance)));
   mu4=mean(xc.^4,2); sevar=sqrt(max(0,(mu4-((nv-3)/(nv-1))*s.std.^4)/nv));
   s.std_ci=sqrt(max(0,[s.std.^2-1.96*sevar,s.std.^2+1.96*sevar]));
  end
  Cs=zeros(p); nc=0;
  for k=ix
   if size(covariances,3)==1,C=covariances;else,C=covariances(:,:,k);end
   if any(~isfinite(C(:))),continue;end
   [R,flag]=chol((C+C')/2);if flag~=0,continue;end
   s.nees(k)=sum((R'\errors(:,k)).^2); Cs=Cs+C;nc=nc+1;
  end
  s.n_covariance_valid=nc;
  if nc>0
   s.mean_predicted_covariance=Cs/nc;s.predicted_std=sqrt(max(0,diag(Cs/nc)));
   for a=1:numel(nominal)
    hits=sum(s.nees<=jog.Core.chi2(nominal(a),p));
    s.coverage_conditional(a)=hits/nc;s.coverage_operational(a)=hits/N;
    s.coverage_wilson(a,:)=jog.Core.wilson(hits,nc);
   end
  end
 end
 function x=quantile(v,p)
  v=sort(v(isfinite(v))); if isempty(v),x=NaN;return;end
  q=1+(numel(v)-1)*p;lo=floor(q);hi=ceil(q);x=v(lo)+(q-lo)*(v(hi)-v(lo));
 end
end
end

function out=linear_suite(id,cfg)
%LINEAR_SUITE Fixed-design experiments J00--J06 (J03 is invariance).
out=struct('id',id,'layer','L1 fixed-design Gaussian','conditions',{{}},'notes','');
switch id
 case 'J00'
  rng(jog.Core.seed(cfg,0,0,0),'twister');C=cfg.identity_cases;
  names={'GLS estimate','GLS covariance','Mixed inverse','Orthogonality','Kernel'};
  err=zeros(C,numel(names));cond=zeros(C,1);designs=cell(C,1);
  for c=1:C
   [O,~]=qr(randn(24));A=O(:,1:4)*diag(.5+2*rand(4,1));T=randn(4,5);
   V=O(:,5:9)*randn(5);V(:,end)=0;U=A*T+V;Z=randn(5);Q=Z*Z'/5+eye(5);
   d=jog.Core.linear(A,U,Q);mix=[A'*A A'*U;U'*A U'*U+(Q\eye(5))];
   expected=[d.Sigma -d.T*d.Q_b_given_r;-d.Q_b_given_r*d.T' d.Q_b_given_r];
   h=[zeros(4,1);1];
   err(c,:)=[jog.Core.relative(d.W,d.W_direct),jog.Core.relative(d.Sigma,d.Sigma_direct),...
    jog.Core.relative(mix\eye(9),expected),norm(A'*d.V,'fro'),norm([A U]*[-d.T*h;h])];
   cond(c)=d.condition_A_scaled;designs{c}=d;
  end
  assert(max(err(:))<1e-8,'J00 algebra verification failed.');
  out.errors=err;out.error_names=names;out.condition=cond;out.designs=designs;
  out.notes='Deterministic matrix identities. Not a camera accuracy experiment.';
 case 'J01'
  g=jog.Camera.geometry(cfg,40,.15,jog.Core.seed(cfg,1,0,0));
  no=jog.Camera.noiseModel(cfg,g,1,'patch');[~,A,B]=jog.Camera.evaluate(g.y_true,g.truth_camera);
  Sl=B*no.Q_local*B';Cl=chol(Sl,'lower');U=Cl\(B*no.G_raw);
  cols={1:6,1:7,1:8,1:10};names={'EOP (6)','+ focal (7)','+ distortion (8)','+ principal point (10)'};
  old=[];
  for c=1:4
   d=jog.Core.linear(Cl\A(:,cols{c}),U,no.Q_b);L=[eye(3),zeros(3,numel(cols{c})-3)];
   [inflation,spectrum]=jog.Core.inflation(d,L);
   nullTolerance=1e-9*max(1,norm(d.V,2));Z=null(d.V,nullTolerance);
   defect=norm(L*d.T*Z,'fro');
   rec=struct('name',names{c},'parameter_columns',cols{c},'design',d,'L_target',L,...
    'position_variance_inflation',inflation,'position_inflation_spectrum',spectrum,...
    'J_drop_min_eigenvalue',NaN,'null_V',Z,'null_V_absolute_tolerance',nullTolerance,...
    'target_estimability_defect',defect,'target_estimable_against_fixed_common_effects',...
    defect<=1e-8*max(1,norm(L*d.T,'fro')));
   if c>1
    rec.J_drop_min_eigenvalue=min(eig((old-d.J+old'-d.J')/2));
    assert(rec.J_drop_min_eigenvalue>=-1e-8*max(1,norm(old,2)),'J01 information nesting failed.');
   end
   out.conditions{c}=rec;old=d.J;
  end
  out.geometry=g;out.noise=no;
  out.notes='Same truth design, observations, loading and LOCAL whitening; only IOP columns are added.';
 case 'J02'
  count=0;
  for rho=cfg.linear.rho
   for s=cfg.linear.s
    count=count+1;A=[sqrt(s);0];U=[sqrt(s) 0;0 sqrt(s)];Q=.04*[1 rho;rho 1];
    d=jog.Core.linear(A,U,Q);rec=mc(d,cfg,2,count);
    rec.rho=rho;rec.s=s;rec.target_floor=.04*(1-rho^2);
    rec.prediction_errors=rec.b-d.Q_b_given_r*d.V'*rec.residual;
    rec.prediction_covariance=cov(rec.prediction_errors');
    out.conditions{count}=rec;
   end
  end
  out.notes='Compact sufficient contrasts of s repeated observations; one hidden and one learned mode. All common effects are redrawn per trial.';
 case 'J03'
  rng(jog.Core.seed(cfg,3,0,0),'twister');err=zeros(cfg.identity_cases,3);records=cell(cfg.identity_cases,1);
  for c=1:cfg.identity_cases
   A=randn(20,4);U=randn(20,3);Q=randn(3);Q=Q*Q'+eye(3);d=jog.Core.linear(A,U,Q);
   [Mb,~]=qr(randn(3));Mb=Mb*diag([.1 2 10]);dp=jog.Core.linear(A,U/Mb,Mb*Q*Mb');
   L=[eye(2) zeros(2)];C=[2 .3;-.2 .5];
   [~,sp0]=jog.Core.inflation(d,L);[~,sp1]=jog.Core.inflation(dp,L);[~,sp2]=jog.Core.inflation(d,C*L);
   err(c,:)=[jog.Core.relative(d.learning_spectrum,dp.learning_spectrum),...
    jog.Core.relative(sp0,sp1),jog.Core.relative(sp0,sp2)];
   records{c}=struct('original',d,'transformed',dp,'M_b',Mb,'L',L,'target_transform',C,...
    'inflation_spectra',[sp0 sp1 sp2]);
  end
  assert(max(err(:))<1e-8,'J03 invariance failed.');out.errors=err;out.records=records;
  out.notes='Coordinate-change identities. Generalized eigenvalues, not individual covariance entries, are invariant.';
 case 'J04'
  s=100;A=[sqrt(s);0;0];U=[sqrt(s);0;0];
  for c=1:numel(cfg.linear.tau)
   tau=cfg.linear.tau(c);d=jog.Core.linear(A,U,.04+tau);
   N=cfg.mc_linear;b=zeros(1,N);noise=zeros(3,N);base=zeros(1,N);added=zeros(1,N);seeds=zeros(1,N);
   for k=1:N
    seeds(k)=jog.Core.seed(cfg,4,0,k);rng(seeds(k),'twister');
    base(k)=.2*randn;added(k)=randn;noise(:,k)=randn(3,1);b(k)=base(k)+sqrt(tau)*added(k);
   end
   z=U*b+noise;estimate=d.W*z;r=(eye(3)-d.H)*z;
   rec=struct('tau',tau,'s',s,'design',d,'seed',seeds,'b',b,'base_b',base,...
    'added_standard_normal',added,'noise',noise,'observations',z,'estimate',estimate,'residual',r,...
    'summary',jog.Core.summarize(estimate,d.Sigma,true(1,N),cfg.nominal),...
    'residual_energy',sum(r.^2,1));
   out.conditions{c}=rec;
  end
  out.notes='Paired base errors across tau; adding an invisible common effect leaves residuals identical, but changes target variance.';
 case 'J05'
  count=0;qb=2;
  for rate=cfg.linear.rates
   for s=cfg.linear.s
    count=count+1;delta=s^(-rate);A=[sqrt(s);0];U=[sqrt(s);sqrt(s)*delta];
    d=jog.Core.linear(A,U,qb);rec=mc(d,cfg,5,count);
    rec.s=s;rec.rate=rate;rec.delta=delta;rec.EAR=1/(1+delta^2);
    if rate<.5,rec.limit=0;elseif rate==.5,rec.limit=1/(1/qb+1);else,rec.limit=qb;end
    out.conditions{count}=rec;
   end
  end
  out.notes='Exact compact Gaussian experiment with information growth s; EAR is geometric, not an uncertainty probability.';
 case 'J06'
  out.layer='L2 reduced pinhole, fixed Jacobian';f=cfg.plane.f;gz=cfg.plane.gamma_z;o=-10;n=30;
  spread=[.005 .01 .02 .05 .1 .2 .4 .6];theta=2*pi*(0:n-1)/n;rho=3*[cos(theta);sin(theta)];
  for c=1:numel(spread)
   z=20*(1+spread(c)*linspace(-.5,.5,n));Z=gz+z;
   a=f*rho./z.^2/cfg.plane.image_std;
   A1=a(:);A2=[a(:),reshape(a.*z,[],1)];U=reshape(a.*(Z-o),[],1);
   dk=jog.Core.linear(A1,U,.01^2);df=jog.Core.linear(A2,U,.01^2);
   w=sum(a.^2,1);Zw=sum(w.*Z)/sum(w);formula=sum(w.*(Z-Zw).^2);
   assert(abs(dk.J-formula)<1e-7*max(1,formula));assert(norm(df.V)<1e-8*norm(U));
   out.conditions{c}=struct('spread',spread(c),'depths',z,'rho',rho,'known_f',dk,'free_f',df,...
    'formula_J',formula,'loading_identity_error',norm(U-A2*[gz-o;1]),'origin_z',o);
  end
  out.notes='Directional depth scale, not rigid TLS registration. Same pointwise local image whitening in fixed/free focal comparison.';
 otherwise,error('Unsupported linear experiment %s',id);
end
end

function rec=mc(d,cfg,suite,condition)
N=cfg.mc_linear;n=size(d.A,1);r=size(d.U,2);
b=zeros(r,N);ee=zeros(n,N);seed=zeros(1,N);C=chol(d.Qb,'lower');
for k=1:N
 seed(k)=jog.Core.seed(cfg,suite,condition,k);rng(seed(k),'twister');
 b(:,k)=C*randn(r,1);ee(:,k)=randn(n,1);
end
z=d.U*b+ee;estimate=d.W*z;residual=(eye(n)-d.H)*z;
rec=struct('design',d,'seed',seed,'b',b,'noise',ee,'observations',z,...
 'truth_parameter',zeros(size(d.A,2),1),'estimate',estimate,'residual',residual,...
 'summary',jog.Core.summarize(estimate,d.Sigma,true(1,N),cfg.nominal));
end

function out=nonlinear_suite(cfg,checkpoint,previous)
%NONLINEAR_SUITE J09: practical observed-data initialization and full GHM.
if nargin<2,checkpoint=[];end
out=struct('id','J09','layer','L3 full nonlinear division camera','conditions',{{}},...
 'notes','Known oracle covariance; observed DLT initialization unless explicitly tagged oracle_local.');
cases={};base=cfg.nonlinear;
for a=base.noise_scales,cases{end+1}=spec('noise_scale',base.baseline_points,base.baseline_spread,a,'patch',a);end
for a=base.depth_spreads
 if abs(a-base.baseline_spread)>1e-12,cases{end+1}=spec('depth_spread',base.baseline_points,a,1,'patch',a);end
end
for a=base.point_counts
 if a~=base.baseline_points,cases{end+1}=spec('point_count',a,base.baseline_spread,1,'patch',a);end
end
for a=base.point_counts,cases{end+1}=spec('global_translation',a,base.baseline_spread,1,'global',a);end
methods=base.methods;
if nargin>=3 && ~isempty(previous),out=previous;end
start=numel(out.conditions)+1;
for ci=start:numel(cases)
 sp=cases{ci};fprintf('  J09 condition %d/%d: %s = %g\n',ci,numel(cases),sp.sweep,sp.x);
 % Geometry uses a namespace disjoint from the per-trial noise seeds.
 gs=cfg.master_seed+200000000+sp.n*1000+round(1000*sp.depth_spread);
 g=jog.Camera.geometry(cfg,sp.n,sp.depth_spread,gs);truth=g.truth_camera;
 no=jog.Camera.noiseModel(cfg,g,sp.noise_scale,sp.kind);N=cfg.mc_nonlinear;nm=numel(methods);
 obs=zeros(5,sp.n,N);localerr=zeros(5*sp.n,N);b=zeros(size(no.Q_b,1),N);seeds=zeros(1,N);
 pools=cell(1,N);runs=cell(nm,N);esterror=nan(10,N,nm);covcommon=nan(10,10,N,nm);covnative=covcommon;
 valid=false(nm,N);factor=cell(1,nm);references=cell(1,nm);
 [~,A0,B0]=jog.Camera.evaluate(g.y_true,truth);
 for mi=1:nm
  factor{mi}=jog.Camera.factor(no,methods{mi});Sm=B0*(factor{mi}*factor{mi}')*B0';
  Lm=chol((Sm+Sm')/2,'lower');[C,~,~,~]=jog.Core.normal(Lm\A0,cfg.solver.rank_tolerance);
  W=C*(Lm\A0)'/Lm*B0;
  references{mi}=struct('nominal_covariance',C,'actual_sampling_covariance',W*no.Q_full*W',...
   'sensitivity',W,'design_is_oracle',true);
 end
 for k=1:N
  seeds(k)=jog.Core.seed(cfg,9,ci,k);rng(seeds(k),'twister');
  localerr(:,k)=no.F_local*randn(5*sp.n,1);b(:,k)=chol(no.Q_b,'lower')*randn(size(no.Q_b,1),1);
  obs(:,:,k)=g.y_true+reshape(localerr(:,k)+no.G_raw*b(:,k),5,[]);
  if strcmp(base.initialization,'observed_DLT_multistart')
   pool=jog.Camera.initialize(obs(:,:,k),cfg);
  elseif strcmp(base.initialization,'oracle_local')
   pool={truth}; % Explicit diagnostic, separately tagged in output.
  else,error('Unknown initialization mode.');end
  pools{k}=pool;
  for mi=1:nm
   r=jog.solve_camera(obs(:,:,k),factor{mi},pool,cfg);
   if ~isempty(r.camera)
    err=jog.Camera.error(r.camera,truth);esterror(:,k,mi)=err;
    r.error_truth_coordinates=err;r.nees_difference_at_estimate=-err;
   end
   valid(mi,k)=r.success;
   if r.success
    covnative(:,:,k,mi)=r.covariance;
    T=eye(10);T(4:6,4:6)=jog.Camera.leftInverse(esterror(4:6,k,mi));
    covcommon(:,:,k,mi)=T*r.covariance*T';
    r.covariance_common_error_coordinates=covcommon(:,:,k,mi);
    if strcmp(methods{mi},'GH_FULL')
     r.predicted_common=chol(no.Q_b,'lower')*r.latent_error(5*sp.n+1:end);
     [~,Ae,Be]=jog.Camera.evaluate(r.adjusted_observations,r.camera);
     Le=chol(Be*no.Q_local*Be','lower');dg=jog.Core.linear(Le\Ae,Le\(Be*no.G_raw),no.Q_b);
     r.common_diagnostics=rmfield(dg,{'H','Omega','W','W_direct','A','U'});
    end
   end
   runs{mi,k}=r;
  end
  if mod(k,max(1,floor(N/5)))==0,fprintf('    %d/%d maps done\n',k,N);end
 end
 summaries=cell(1,nm);
 for mi=1:nm
  e=esterror(:,:,mi);S=covcommon(:,:,:,mi);Sn=covnative(:,:,:,mi);
  % Scalar error components use a common truth-anchored chart for moments.
  ss=jog.Core.summarize(e,S,valid(mi,:),cfg.nominal);
  native=jog.Core.summarize(-e,Sn,valid(mi,:),cfg.nominal);
  ss.coverage_conditional=native.coverage_conditional;ss.coverage_operational=native.coverage_operational;
  ss.coverage_wilson=native.coverage_wilson;ss.nees=native.nees;
  ss.position=jog.Core.summarize(e(1:3,:),S(1:3,1:3,:),valid(mi,:),cfg.nominal);
  ss.eop=jog.Core.summarize(e(1:6,:),S(1:6,1:6,:),valid(mi,:),cfg.nominal);
  enative=jog.Core.summarize(-e(1:6,:),Sn(1:6,1:6,:),valid(mi,:),cfg.nominal);
  ss.eop.coverage_conditional=enative.coverage_conditional;
  ss.eop.coverage_operational=enative.coverage_operational;
  ss.eop.coverage_wilson=enative.coverage_wilson;ss.eop.nees=enative.nees;
  ss.rotation_rmse_deg=sqrt(mean(sum(e(4:6,valid(mi,:)).^2,1)))*180/pi;
  ss.focal_relative_rmse=sqrt(mean((exp(e(7,valid(mi,:)))-1).^2));
  ss.raw_reprojection_coordinate_rmse=cellfun(@(r)r.raw_reprojection_coordinate_rmse,runs(mi,:));
  ss.position_error_norm=sqrt(sum(e(1:3,:).^2,1));
  ss.ellipsoid_maxaxis95=nan(1,N);ss.ellipsoid_volume95=nan(1,N);
  for k=find(valid(mi,:))
   ev=eig(Sn(1:3,1:3,k));axes95=sqrt(jog.Core.chi2(.95,3)*max(0,ev));
   ss.ellipsoid_maxaxis95(k)=max(axes95);ss.ellipsoid_volume95(k)=4*pi/3*prod(axes95);
  end
  ss.median_maxaxis95=jog.Core.quantile(ss.ellipsoid_maxaxis95,.5);
  ss.mean_seconds=mean(cellfun(@(r)r.elapsed_seconds,runs(mi,:)));
  ss.status=cellfun(@(r)r.status,runs(mi,:),'UniformOutput',false);
  summaries{mi}=ss;
 end
 out.conditions{ci}=struct('spec',sp,'geometry_id',gs,'geometry',g,'noise_model',no,'methods',{methods},...
  'oracle_reference',{references},'covariance_factors',{factor},'trial_id',1:N,'map_id',1:N,'seed',seeds,...
  'observations',obs,'true_local_errors',localerr,'true_common_effects',b,...
  'initialization_mode',base.initialization,'shared_initializer_pool',{pools},'runs',{runs},...
  'errors',esterror,'covariance_common',covcommon,'covariance_at_estimate',covnative,...
  'valid',valid,'summary',{summaries});
 if ~isempty(checkpoint),checkpoint(out);end
end
end
function s=spec(sweep,n,spread,noise,kind,x)
s=struct('sweep',sweep,'n',n,'depth_spread',spread,'noise_scale',noise,'kind',kind,'x',x);
end

function out=plane_suite(id,cfg)
%PLANE_SUITE Exact sufficient-statistic simulation of independent Gaussian
% image/depth observations. No point observations are generated then thrown
% away: lambda_hat and mean depth are the generated data. The complete design,
% common errors, standard normals and statistics are retained in output.mat.
out=struct('id',id,'layer','L2 Gaussian sufficient-statistic pinhole experiment',...
 'conditions',{{}},'notes','');p=cfg.plane;cases={};
if strcmp(id,'J07')
 for sb=p.region_std
  for n=p.n,cases{end+1}=spec('points_per_plane',n,p.depths,sb,0,n);end %#ok<AGROW>
 end
 for d=p.group_counts,cases{end+1}=spec('independent_planes',max(p.n),linspace(10,25,d),p.region_std(1),0,d);end
 for spread=p.depth_spreads,cases{end+1}=spec('relative_depth_spread',max(p.n),20*(1+spread*linspace(-.5,.5,4)),p.region_std(1),0,spread);end
elseif strcmp(id,'J08')
 for sg=p.global_stds,cases{end+1}=spec('global_datum_std',max(p.n),p.depths,p.region_std(1),sg,sg);end
else,error('Unsupported plane experiment');end
for ci=1:numel(cases)
 c=cases{ci};d=numel(c.depths);N=cfg.mc_plane;n=c.n;
 truth=[p.gamma_z;p.f];lambda=p.f./c.depths(:);M=[ones(d,1),1./lambda];
 Sigma=c.region_std^2*eye(d)+c.global_std^2*ones(d);
 H=(M'*(Sigma\M))\(M'/Sigma);floorC=(M'*(Sigma\M))\eye(2);
 weights=(Sigma\ones(d,1))/(ones(1,d)*(Sigma\ones(d,1)));
 floorKnown=1/(ones(1,d)*(Sigma\ones(d,1)));
 Rn=n*p.horizontal_radius^2;
 varLambda=p.image_std^2/Rn*ones(d,1);
 SigmaFinite=Sigma+diag(p.local_depth_std^2/n+(p.f./lambda.^2).^2.*varLambda);
 Cfinite=H*SigmaFinite*H';CfiniteKnown=weights'*SigmaFinite*weights;
 est=nan(2,N);known=nan(1,N);guard=false(1,N);estimateValid=false(1,N);
 lh=zeros(d,N);xd=zeros(d,N);b=zeros(d,N);globalb=zeros(1,N);epsLambda=zeros(d,N);epsDepth=zeros(d,N);
 seeds=zeros(1,N);information=zeros(1,N);reasons=cell(1,N);
 for k=1:N
  seeds(k)=jog.Core.seed(cfg,str2double(id(2:end)),ci,k);rng(seeds(k),'twister');
  b(:,k)=c.region_std*randn(d,1);globalb(k)=c.global_std*randn;
  epsLambda(:,k)=sqrt(varLambda).*randn(d,1);epsDepth(:,k)=p.local_depth_std/sqrt(n)*randn(d,1);
  lh(:,k)=lambda+epsLambda(:,k);xd(:,k)=p.gamma_z+c.depths(:)+b(:,k)+globalb(k)+epsDepth(:,k);
  inRange=all(lh(:,k)>=p.guard_lambda(1) & lh(:,k)<=p.guard_lambda(2));
  if inRange
   Mh=[ones(d,1),1./lh(:,k)];info=Mh'*(Sigma\Mh);information(k)=min(eig((info+info')/2));
   if information(k)>=p.guard_min_information
    est(:,k)=info\(Mh'*(Sigma\xd(:,k)));known(k)=weights'*(xd(:,k)-p.f./lh(:,k));
    guard(k)=true;reasons{k}='accepted';
   else,reasons{k}='guard_rank';end
  else,reasons{k}='guard_magnification';end
  if ~guard(k),est(:,k)=p.fallback;known(k)=p.fallback(1);end
  estimateValid(k)=all(isfinite(est(:,k)));
 end
 errors=est-truth;
 % Fallbacks contribute to unconditional moments but do not issue confidence regions.
 Ctrial=repmat(Cfinite,1,1,N);Ctrial(:,:,~guard)=NaN;
 CknownTrial=repmat(CfiniteKnown,1,1,N);CknownTrial(:,:,~guard)=NaN;
 allSummary=jog.Core.summarize(errors,Ctrial,estimateValid,cfg.nominal);
 successSummary=jog.Core.summarize(errors,Ctrial,guard,cfg.nominal);
 knownSummary=jog.Core.summarize(known-p.gamma_z,CknownTrial,true(1,N),cfg.nominal);
 theta=2*pi*(0:n-1)/n;rho=p.horizontal_radius*[cos(theta);sin(theta)];
 out.conditions{ci}=struct('spec',c,'truth',truth,'lambda',lambda,'M',M,'Sigma_common',Sigma,...
  'H_limit',H,'floor_covariance',floorC,'floor_known_f',floorKnown,'first_order_finite_covariance',Cfinite,...
  'first_order_finite_covariance_known_f',CfiniteKnown,...
  'horizontal_coordinates_per_plane',rho,'R_n',Rn,'seed',seeds,'lambda_hat',lh,'mean_depth_observed',xd,...
  'regional_effect',b,'global_effect',globalb,'lambda_error',epsLambda,'mean_local_depth_error',epsDepth,...
  'estimate',est,'known_f_estimate',known,'errors',errors,'guard_accepted',guard,...
  'guard_min_information',information,'status',{reasons},'guard_rate',1-mean(guard),...
  'summary_all_including_fallback',allSummary,'summary_accepted',successSummary,'summary_known_f',knownSummary,...
  'depth_cv',std(c.depths,1)/mean(c.depths),'variance_inflation_free_f',floorC(1,1)/floorKnown);
end
out.notes=['Independent map common effects are redrawn each trial. The generator samples exact Gaussian sufficient statistics. ',...
 'Guard fallback trials are retained in unconditional moments. Finite covariance is first-order, the horizontal floor is a limiting result.'];
end
function s=spec(sweep,n,z,sb,sg,x)
s=struct('sweep',sweep,'n',n,'depths',z,'region_std',sb,'global_std',sg,'x',x);
end

function result=solve_camera(y,F,pool,cfg)
%SOLVE_CAMERA Local constrained adjustment in latent errors e=F*v.
% All methods share exactly the same observed-data initializer pool.
% Minimizes .5*||v||^2 subject to psi(y-F*v,c)=0. Redundant full-covariance
% factors are valid; their minimum-norm latent representation is selected.
t=tic; candidates=cell(size(pool));best=Inf;selected=0;
for j=1:numel(pool)
 candidates{j}=one(y,F,pool{j},cfg);
 if candidates{j}.success && candidates{j}.cost<best,best=candidates{j}.cost;selected=j;end
end
if selected==0
 result=blank(y,F);result.status='no_valid_initializer';
 if ~isempty(pool)
  result.status='nonconverged_all_candidates';
  scores=cellfun(@(x)x.final_merit,candidates);[~,j]=min(scores);
  result=candidates{j};result.success=false;result.status=['all_candidates_failed:' result.status];
 end
else,result=candidates{selected};end
result.selected_candidate=selected;result.candidate_count=numel(pool);
summaries=cell(size(candidates));
for j=1:numel(candidates)
 cc=candidates{j};summaries{j}=struct('camera',cc.camera,'success',cc.success,'status',cc.status,...
 'cost',cc.cost,'iterations',cc.iterations,'constraint_inf',cc.constraint_inf,'history',cc.history,'physical_valid',cc.physical_valid,...
 'active_parameter_bound',cc.active_parameter_bound);
end
result.candidates=summaries;result.elapsed_seconds=toc(t);
end

function r=one(y,F,c,cfg)
opt=cfg.solver;v=zeros(size(F,2),1);rho=1;history=nan(opt.max_iterations,7);
r=blank(y,F);r.camera=c;Y=y(:);status='nonconverged';it=0;
for it=1:opt.max_iterations
 mu=reshape(Y-F*v,5,[]);[psi,A,B,ok,reason]=jog.Camera.evaluate(mu,c);
 if ~ok,status=reason;break;end
 BF=B*F;S=BF*BF';[Cs,flag]=chol((S+S')/2,'lower');
 if flag,status='singular_condition_covariance';break;end
 w=psi+BF*v;Aw=Cs\A;ww=Cs\w;
 try,[Ni,~,rankA,condA]=jog.Core.normal(Aw,opt.rank_tolerance);
 catch,status='rank_deficient';break;end
 delta=Ni*Aw'*ww;lambda=Cs'\(Cs\(w-A*delta));vnew=BF'*lambda;dv=vnew-v;
 scaled=max(abs(delta)./opt.parameter_scale);closure=norm(psi,inf);
 if scaled<opt.step_tolerance && norm(dv)/max(1,norm(v))<opt.step_tolerance && closure<opt.constraint_tolerance
  status='success';history(it,:)=[.5*(v'*v),closure,scaled,0,condA,norm(dv),rho];break;
 end
 rho=max(rho,1.5*norm(lambda,inf)+1);merit=.5*(v'*v)+rho*norm(psi,1);
 slope=v'*dv-rho*norm(psi,1);accepted=false;step=1;
 for ls=1:opt.max_linesearch
  trial=jog.Camera.step(c,step*delta);vt=v+step*dv;
  if ~bounds(trial,opt),step=step/2;continue;end
  [pt,~,~,good]=jog.Camera.evaluate(reshape(Y-F*vt,5,[]),trial);
  if good
   mt=.5*(vt'*vt)+rho*norm(pt,1);
   if mt<=merit+1e-4*step*min(slope,-eps*max(1,merit))
    accepted=true;break;
   end
  end
  step=step/2;
 end
 history(it,:)=[.5*(v'*v),closure,scaled,step,condA,norm(dv),rho];
 if ~accepted
  % Accept stationarity at a stricter feasibility threshold only; no silent success.
  if closure<opt.constraint_tolerance && scaled<10*opt.step_tolerance && norm(dv)/max(1,norm(v))<10*opt.step_tolerance
   status='success';
  else,status='line_search_failed';end
  break;
 end
 c=trial;v=vt;
end
r.camera=c;r.latent_error=v;r.adjusted_observations=reshape(Y-F*v,5,[]);
r.observation_correction=reshape(F*v,5,[]);r.cost=.5*v'*v;r.status=status;
r.iterations=it;r.history=history(1:it,:);r.history_columns={'cost','closure_inf','scaled_step','line_step','scaled_condition','latent_step','merit_penalty'};
[psi,A,B,ok,~]=jog.Camera.evaluate(r.adjusted_observations,c);
r.constraint_inf=norm(psi,inf);r.final_merit=r.cost+rho*norm(psi,1);
r.success=strcmp(status,'success') && ok;r.physical_valid=ok;
r.active_parameter_bound=nearBounds(c,opt);
if r.success
 S=B*(F*F')*B';[Cs,flag]=chol((S+S')/2,'lower');
 if ~flag
  try
   [C,~,ra,cond]=jog.Core.normal(Cs\A,opt.rank_tolerance);
   r.covariance=C;r.rank=ra;r.condition_scaled=cond;
   r.sensitivity=C*(Cs\A)'/Cs*B;
   lambda=S\(B*F*v);r.stationarity_norm=norm(A'*lambda,inf);
  catch,r.success=false;r.status='covariance_unavailable';end
 else,r.success=false;r.status='singular_condition_covariance';end
end
if r.active_parameter_bound,r.success=false;r.status='active_parameter_bound';end
uv=jog.Camera.project(y(3:5,:),c);r.raw_reprojection=y(1:2,:)-uv;
r.raw_reprojection_coordinate_rmse=sqrt(mean(r.raw_reprojection(:).^2));
if ~cfg.save_candidate_history,r.history=[];end
end
function r=blank(y,F)
r=struct('success',false,'status','not_run','camera',[],...
 'covariance',nan(10),'sensitivity',[],'rank',NaN,'condition_scaled',NaN,...
 'latent_error',nan(size(F,2),1),'adjusted_observations',nan(size(y)),...
 'observation_correction',nan(size(y)),'cost',Inf,'final_merit',Inf,...
 'iterations',0,'history',[],'constraint_inf',Inf,'physical_valid',false,...
 'active_parameter_bound',false,'stationarity_norm',NaN,...
 'raw_reprojection',nan(2,size(y,2)),'raw_reprojection_coordinate_rmse',NaN);
end
function yes=bounds(c,opt)
f=c.scale*exp(c.phi);yes=isfinite(f)&&f>opt.focal_range(1)&&f<opt.focal_range(2)...
 &&c.kappa>opt.kappa_range(1)&&c.kappa<opt.kappa_range(2)&&all(abs(c.pp)<opt.principal_point_absmax);
end
function yes=nearBounds(c,opt)
f=c.scale*exp(c.phi);tol=1e-6;
yes=min(abs(f-opt.focal_range))<tol || min(abs(c.kappa-opt.kappa_range))<tol || any(abs(abs(c.pp)-opt.principal_point_absmax)<tol);
end

classdef Analysis
methods(Static)
function s=condition(file,c,cfg)
 started=tic;d=jog2.Store.design(file,c);E=[];CN=[];CC=[];valid=[];cost=[];lin=[];
 branches=[];gap=[];clusters=[];status={};reproj=[];ids=[];
 for j=1:numel(c.batches)
  b=jog2.Store.read(file,c.batches{j});
  if mod(j,10)==0||j==numel(c.batches),fprintf('  Statistics batch %d/%d | %.1f s\n',j,numel(c.batches),toc(started));end
  E=cat(2,E,b.errors);CN=cat(3,CN,b.covariance_native);CC=cat(3,CC,b.covariance_common);
  valid=cat(2,valid,b.valid);cost=cat(2,cost,b.cost);lin=cat(2,lin,b.linear_error);ids=[ids b.trial_id];
  rr=squeeze(sqrt(mean(reshape(b.reprojection,2*d.spec.n,numel(d.methods),[]).^2,1)));
  if numel(d.methods)==1,rr=reshape(rr,1,[]);end;reproj=[reproj rr];
  [bc,bg,cl]=jog2.Analysis.branches(b,d,cfg);branches=[branches bc];gap=[gap bg];clusters=cat(3,clusters,cl);
  for m=1:numel(d.methods),status{m,j}=b.meta.status_dictionary(b.status_code(m,:));end
 end
 [ids,ord]=sort(ids);E=E(:,ord,:);CN=CN(:,:,ord,:);CC=CC(:,:,ord,:);valid=valid(:,ord);
 cost=cost(:,ord);lin=lin(:,ord,:);branches=branches(:,ord);gap=gap(:,ord);reproj=reproj(:,ord);
 N=numel(ids);s=struct('suite',c.suite,'run_id',c.run_id,'spec',c.spec,'methods',{d.methods},...
 'trial_ids',ids,'method',{{}},'geometry',jog2.Util.without(d.geometry,{'master_xyz','master_uv','master_depth_u'}),...
 'nested_diagnostics',{d.nested_diagnostics});
 blocks={1:3,4:6,7,8,9:10,1:6,1:10};names={'position','rotation','log_f','kappa','principal_point','eop','full'};
 for m=1:numel(d.methods)
  e=E(:,:,m);sn=CN(:,:,:,m);sc=CC(:,:,:,m);ok=valid(m,:)&all(isfinite(e),1);
  a=struct('label',d.methods{m},'n_total',N,'n_valid',nnz(ok),'blocks',struct(),...
    'cost',cost(m,:),'reprojection_rmse',reproj(m,:),'branch_count',branches(m,:),...
    'candidate_cost_gap',gap(m,:),'cluster_counts_sensitivity',clusters(:,m,:),...
    'metric_scale',cfg.solver.parameter_scale);
  for z=1:numel(blocks)
   ix=blocks{z};summary=jog.Core.summarize(e(ix,:),sc(ix,ix,:),ok,cfg.nominal);
   native=jog.Core.summarize(-e(ix,:),sn(ix,ix,:),ok,cfg.nominal);
   fs={'nees','coverage_conditional','coverage_operational','coverage_wilson','n_covariance_valid'};
   for f=1:numel(fs),summary.(fs{f})=native.(fs{f});end
   summary.scatter=sqrt(trace(summary.covariance));summary.predicted_scatter=sqrt(trace(summary.mean_predicted_covariance));
   summary.nees_mean=mean(summary.nees(isfinite(summary.nees)));
   summary.nees_quantiles=arrayfun(@(p)jog.Core.quantile(summary.nees,p),[.5 .9 .95 .99]);
   a.blocks.(names{z})=summary;
  end
  C0=d.oracle_reference{m}.nominal_covariance;Ct=d.oracle_reference{m}.actual_sampling_covariance;
  a.linear=jog.Core.summarize(lin(:,:,m),C0,true(1,N),cfg.nominal);
  a.actual_fixed_nominal=jog.Core.summarize(e,C0,ok,cfg.nominal);
  a.actual_fixed_sampling=jog.Core.summarize(e,Ct,ok,cfg.nominal);
  a.linear_sampling=jog.Core.summarize(lin(:,:,m),Ct,true(1,N),cfg.nominal);
  rem=e-lin(:,:,m);L=chol((Ct+Ct')/2,'lower');
  a.remainder=struct('raw_rms',NaN,'normalized_rms',NaN,'per_map_squared',nan(1,N),...
   'reference','true sampling covariance at this epsilon','conditioning','valid fit');
  if any(ok)
   a.remainder.raw_rms=sqrt(mean(sum(rem(:,ok).^2,1)));
   a.remainder.per_map_squared(ok)=sum((L\rem(:,ok)).^2,1);
   a.remainder.normalized_rms=sqrt(mean(a.remainder.per_map_squared(ok)));
  end
  a.bias_decomposition=struct();a.generalized=struct();
  if nnz(ok)>=2
   x=e(:,ok);mu=mean(x,2);S=cov(x');C=chol(C0,'lower');MSE=x*x'/size(x,2);
   bias=sum((C\mu).^2);scatter=(size(x,2)-1)/size(x,2)*trace(C\S/C');
   total=mean(sum((C\x).^2,1));
   a.bias_decomposition=struct('bias',mu,'bias_standard_error',sqrt(diag(S)/size(x,2)),...
    'centered_covariance',S,'MSE',MSE,'bias_nees',bias,'scatter_nees',scatter,...
    'mean_fixed_nees',total,'identity_error',abs(total-bias-scatter));
   D=diag(cfg.solver.parameter_scale);Sa=D\S/D;Ca=D\a.blocks.full.mean_predicted_covariance/D;
   [R,p]=chol((Ca+Ca')/2,'lower');
   if p==0
    W=R\Sa/R';[vec,ev]=eig((W+W')/2);[lam,ix]=sort(diag(ev),'descend');v=R'\vec(:,ix);
    v=v./sqrt(sum(v.^2,1));energy=zeros(5,10);
    for bb=1:5,energy(bb,:)=sum(v(blocks{bb},:).^2,1);end
    a.generalized=struct('covariance_eigenvalues',lam,'dimensionless_contrasts',v,...
      'block_coefficient_shares',energy,'metric',cfg.solver.parameter_scale,...
      'interpretation','contrast coefficients, not invariant physical variance shares');
   end
  end
  nu=2*d.spec.n-10;vf=2*cost(m,:)/nu;good=ok&isfinite(vf);
  reject=(2*cost(m,:)<jog.Core.chi2(.025,nu)|2*cost(m,:)>jog.Core.chi2(.975,nu))&good;
  a.variance_factor=struct('values',vf,'df',nu,'mean',mean(vf(good)),...
   'quantiles',arrayfun(@(p)jog.Core.quantile(vf(good),p),[.25 .5 .75 .95]),...
   'rejection_rate',sum(reject)/max(1,nnz(good)),'rejection_wilson',jog.Core.wilson(sum(reject),nnz(good)),...
   'n_valid',nnz(good),'known_absolute_scale',1,'covariance_rescaled',false);
  a.variance_components=jog2.Analysis.components(d,m);
  s.method{m}=a;
 end
 if isfield(d,'similarity'),s.similarity=d.similarity;end
end
function [count,gap,counts]=branches(b,d,cfg)
 M=numel(d.methods);N=numel(b.trial_id);count=zeros(M,N);gap=nan(M,N);counts=zeros(9,M,N);
 for m=1:M
  for k=1:N
   sel=find(b.candidate_info(1,:)==m&b.candidate_info(2,:)==b.trial_id(k)&b.candidate_info(4,:)>0);
   [~,ord]=sort(b.candidate_info(5,sel));sel=sel(ord);nc=numel(sel);dist=zeros(nc);
   for a=1:nc
    ca=jog2.Util.vecCam(b.candidate_camera(:,sel(a)),d.geometry.truth_camera.scale);
    for z=a+1:nc
     cz=jog2.Util.vecCam(b.candidate_camera(:,sel(z)),d.geometry.truth_camera.scale);
     dist(a,z)=norm(jog.Camera.error(ca,cz)./cfg.solver.parameter_scale);dist(z,a)=dist(a,z);
    end
   end
   costs=b.candidate_info(5,sel);if nc>1,gap(m,k)=costs(2)-costs(1);end
   pos=0;
   for tol=cfg.analysis.cluster_distance
    for ct=cfg.analysis.cluster_cost
     pos=pos+1;groups={};
     for a=1:nc
      placed=false;
      for gr=1:numel(groups)
       ix=groups{gr};
       if all(dist(a,ix)<=tol)&&all(abs(costs(a)-costs(ix))<=ct*max(1,abs(costs(a))))
        groups{gr}(end+1)=a;placed=true;break;
       end
      end
      if ~placed,groups{end+1}=a;end
     end
     counts(pos,m,k)=numel(groups);
    end
   end
   count(m,k)=counts(5,m,k);
  end
 end
end
function out=components(d,m)
 no=d.noise_model;W=d.oracle_reference{m}.sensitivity;n=d.spec.n;
 Qi=zeros(5*n);Qx=Qi;
 for i=1:n,a=5*i-4:5*i-3;b=5*i-2:5*i;Qi(a,a)=no.Q_local(a,a);Qx(b,b)=no.Q_local(b,b);end
 C={W*Qi*W',W*Qx*W'};names={'image','local_XYZ'};sumc=C{1}+C{2};
 for k=1:numel(no.components)
  ix=no.components{k}.columns;G=no.G_raw(:,ix);q=no.Q_b(ix,ix);
  cc=W*G*q*G'*W';C{end+1}=cc;names{end+1}=no.components{k}.name;sumc=sumc+cc;
 end
 actual=d.oracle_reference{m}.actual_sampling_covariance;
 out=struct('names',{names},'covariance',{C},'sum_error',jog.Core.relative(sumc,actual),...
 'reference_local',d.decomposition.N_local_inverse,...
 'optimal_shared_increment',d.decomposition.Gamma*d.decomposition.Q_b_given_r*d.decomposition.Gamma');
end
function p=population(o)
 p=struct('conditions',{{}},'paired_differences',{{}});
 sel=find(cellfun(@(c)strcmp(c.suite,'J12'),o.conditions));if isempty(sel),return;end
 labels=o.summaries{sel(1)}.methods;cfg=o.config;
 for regime=1:size(cfg.j12.regimes,1)
  ix=sel(cellfun(@(c)c.spec.x==regime,o.conditions(sel)));v=nan(numel(ix),numel(labels));
  ids=zeros(size(ix));wilsonUpper=nan(size(v));conditional=nan(size(v));
  for g=1:numel(ix),s=o.summaries{ix(g)};ids(g)=s.spec.geometry_id;
   for m=1:numel(labels),z=find(s.method{m}.blocks.full.nominal==.95);v(g,m)=s.method{m}.blocks.full.coverage_operational(z);conditional(g,m)=s.method{m}.blocks.full.coverage_conditional(z);wilsonUpper(g,m)=s.method{m}.blocks.full.coverage_wilson(z,2);end
  end
  boot=nan(cfg.analysis.bootstrap,size(v,2));r=jog2.Util.analysisStream(cfg,regime,0);
  for b=1:size(boot,1),sample=randi(r,size(v,1),1,size(v,1));boot(b,:)=mean(v(sample,:),1,'omitnan');end
  p.conditions{end+1}=struct('regime',regime,'geometry_ids',ids,'methods',{labels},'coverage',v,...
   'conditional_coverage',conditional,'fraction_wilson_upper_below90',mean(wilsonUpper<.9,1),...
   'minimum',min(v,[],1),'maximum',max(v,[],1),'mean',mean(v,1,'omitnan'),'median',median(v,1,'omitnan'),'q25',arrayfun(@(m)jog.Core.quantile(v(:,m),.25),1:size(v,2)),...
   'q75',arrayfun(@(m)jog.Core.quantile(v(:,m),.75),1:size(v,2)),...
   'fraction_observed_below90',mean(v<.9,1),'cluster_bootstrap_means',boot,...
   'cluster_ci',[arrayfun(@(m)jog.Core.quantile(boot(:,m),.025),1:size(v,2));...
   arrayfun(@(m)jog.Core.quantile(boot(:,m),.975),1:size(v,2))]);
 end
 if ~isempty(p.conditions)
  base=p.conditions{1};
  for rr=2:numel(p.conditions)
   other=p.conditions{rr};[ids,ia,ib]=intersect(base.geometry_ids,other.geometry_ids);
   delta=other.coverage(ib,:)-base.coverage(ia,:);boot=zeros(cfg.analysis.bootstrap,size(delta,2));
   rs=jog2.Util.analysisStream(cfg,80+rr,0);
   for b=1:size(boot,1),draw=randi(rs,numel(ids),1,numel(ids));boot(b,:)=mean(delta(draw,:),1,'omitnan');end
   ci=[arrayfun(@(m)jog.Core.quantile(boot(:,m),.025),1:size(delta,2));...
       arrayfun(@(m)jog.Core.quantile(boot(:,m),.975),1:size(delta,2))];
   p.paired_differences{end+1}=struct('reference_regime',1,'regime',rr,'geometry_ids',ids,...
    'differences',delta,'mean',mean(delta,1,'omitnan'),'cluster_ci',ci,'bootstrap_means',boot);
  end
 end
end
end
end

classdef Archive
%ARCHIVE Self-contained MAT payloads without a flat MATLAB variable directory.
% /jog_payload/<prefix> contains bytes of one ordinary, bounded MAT shard.
% MATLAB load(file,'output') reads metadata; Store.read decodes payloads.
methods(Static)
function tf=isArchive(file)
 tf=false;if ~exist(file,'file'),return;end
 try,f=H5F.open(file,'H5F_ACC_RDONLY','H5P_DEFAULT');c=onCleanup(@()H5F.close(f));tf=H5L.exists(f,'/jog_payload','H5P_DEFAULT');catch,end
end
function create(file,o)
 output=o;save(file,'output','-v7.3');
 h5create(file,'/jog_payload/format_version',[1 1],'Datatype','uint8');h5write(file,'/jog_payload/format_version',uint8(1));
 h5writeatt(file,'/jog_payload','format','MAT-shard-bytes-v1');
end
function n=rootCount(file)
 f=H5F.open(file,'H5F_ACC_RDONLY','H5P_DEFAULT');c=onCleanup(@()H5F.close(f));
 g=H5G.open(f,'/');cg=onCleanup(@()H5G.close(g));i=H5G.get_info(g);n=double(i.nlinks);
end
function path=path(e)
 path=['/jog_payload/' e.prefix];
end
function tf=ready(file,e,token)
 if nargin<3,token='';end
 tf=false;path=jog2.Archive.path(e);
 try
  tf=h5readatt(file,path,'committed')==1;
  if isfield(e,'sha256')&&~isempty(e.sha256),tf=tf&&strcmp(h5readatt(file,path,'sha256'),e.sha256);end
  if ~isempty(token),tf=tf&&strcmp(h5readatt(file,path,'analysis_token'),token);end
 catch,tf=false;end
end
function e=normalize(e)
 if isfield(e,'variables'),e=rmfield(e,'variables');end
 e.archive_path=jog2.Archive.path(e);
end
function e=putFile(file,e,source,token)
 if nargin<4,token='';end
 % Verify immutable source before reusing a completed copy.
 hash=jog2.Util.filehash(source);
 if isfield(e,'sha256')&&~isempty(e.sha256),assert(strcmp(hash,e.sha256),'jog2:SourceChecksum','Source checksum mismatch: %s',source);end
 e.sha256=hash;e.bytes=dir(source).bytes;e=jog2.Archive.normalize(e);
 if jog2.Archive.ready(file,e,token),return;end
 path=e.archive_path;
 fid=H5F.open(file,'H5F_ACC_RDWR','H5P_DEFAULT');
 if H5L.exists(fid,path,'H5P_DEFAULT'),H5L.delete(fid,path,'H5P_DEFAULT');end;H5F.close(fid);
 chunk=min(2^20,e.bytes);assert(chunk>0);
 h5create(file,path,[e.bytes 1],'Datatype','uint8','ChunkSize',[chunk 1]);
 h5writeatt(file,path,'committed',uint8(0));
 f=fopen(source,'rb');assert(f>=0);cl=onCleanup(@()fclose(f));at=1;
 while at<=e.bytes
  x=fread(f,min(chunk,e.bytes-at+1),'*uint8');assert(~isempty(x));h5write(file,path,x,[at 1],[numel(x) 1]);at=at+numel(x);
 end
 h5writeatt(file,path,'sha256',hash);h5writeatt(file,path,'kind',e.kind);
 h5writeatt(file,path,'analysis_token',token);h5writeatt(file,path,'committed',uint8(1));
end
function e=putValue(file,prefix,value,kind,token)
 if nargin<5,token='';end
 tmp=[tempname '.mat'];cl=onCleanup(@()jog2.Archive.removeTemp(tmp));vars=struct();
 if strcmp(kind,'batch'),names=fieldnames(value);for k=1:numel(names),vars.([prefix '_' names{k}])=value.(names{k});end
 else,vars.(prefix)=value;end
 save(tmp,'-struct','vars','-v7.3');
 e=struct('prefix',prefix,'kind',kind,'file','','sha256','','bytes',0);
 e=jog2.Archive.putFile(file,e,tmp,token);
end
function [path,clean]=extract(file,e)
 assert(jog2.Archive.ready(file,e),'jog2:PayloadIncomplete','Incomplete/missing payload: %s',e.prefix);
 path=[tempname '.mat'];clean=onCleanup(@()jog2.Archive.removeTemp(path));
 dataset=jog2.Archive.path(e);info=h5info(file,dataset);n=prod(info.Dataspace.Size);
 f=fopen(path,'wb');assert(f>=0);cf=onCleanup(@()fclose(f));
 digest=java.security.MessageDigest.getInstance('SHA-256');chunk=2^20;
 for first=1:chunk:n
  x=h5read(file,dataset,[first 1],[min(chunk,n-first+1) 1]);fwrite(f,x,'uint8');digest.update(x(:));
 end
 clear cf;
 hash=lower(reshape(dec2hex(typecast(digest.digest(),'uint8'),2)',1,[]));
 assert(strcmp(hash,h5readatt(file,dataset,'sha256')),'jog2:PayloadChecksum','Payload checksum mismatch');
end
function v=read(file,e)
 [tmp,clean]=jog2.Archive.extract(file,e);s=load(tmp); %#ok<NASGU>
 v=jog2.Archive.unpack(s,e);
end
function v=unpack(s,e)
 if strcmp(e.kind,'batch')
  v=struct();fn=fieldnames(s);
  for k=1:numel(fn),assert(startsWith(fn{k},[e.prefix '_']));v.(fn{k}(numel(e.prefix)+2:end))=s.(fn{k});end
 else,v=s.(e.prefix);end
end
function e=entry(file,prefix,kind)
 e=struct('prefix',prefix,'kind',kind,'file','','sha256',h5readatt(file,['/jog_payload/' prefix],'sha256'),...
 'bytes',prod(h5info(file,['/jog_payload/' prefix]).Dataspace.Size),'archive_path',['/jog_payload/' prefix]);
end
function removeTemp(file)
 if exist(file,'file'),delete(file);end
end
end
end

classdef Batch
methods(Static)
function b=run(d,cfg,ids)
 n=d.spec.n;N=numel(ids);nm=numel(d.methods);no=d.noise_model;
 b=struct('trial_id',ids,'observations',zeros(5,n,N),'local_errors',zeros(5*n,N),...
 'common_effects',zeros(size(no.Q_b,1),N),'eta',zeros(5*n,N),...
 'z_local',zeros(size(no.F_local,2),N),'z_common',zeros(size(no.L_b,2),N),...
 'rng_id',zeros(2,N),'errors',nan(10,N,nm),'covariance_common',nan(10,10,N,nm),...
 'covariance_native',nan(10,10,N,nm),'valid',false(nm,N),...
 'linear_error',nan(10,N,nm),'cameras',nan(16,nm,N),'cost',nan(nm,N),...
 'iterations',zeros(nm,N),'closure',nan(nm,N),'stationarity',nan(nm,N),...
 'physical',false(nm,N),'active_bound',false(nm,N),'rank',nan(nm,N),...
 'condition_scaled',nan(nm,N),'elapsed',nan(nm,N),'selected_candidate',zeros(nm,N),...
 'reprojection',nan(2,n,nm,N),'adjusted',nan(5,n,nm,N),'correction',nan(5,n,nm,N),...
 'sensitivity',nan(10,5*n,nm,N),'latent_values',zeros(0,1),'latent_offset',zeros(2,nm,N),...
 'history_values',zeros(0,7),'history_offset',zeros(2,nm,N),...
 'candidate_camera',zeros(16,0),'candidate_info',zeros(9,0),...
 'candidate_history',zeros(0,7),'candidate_history_offset',zeros(2,0),...
 'initializer_camera',zeros(16,0),'initializer_trial',zeros(1,0),...
 'status_code',zeros(nm,N),'candidate_status_code',zeros(1,0),...
 'meta',struct('status_dictionary',{{}},'error_messages',{{}},'candidate_physical_available',true));
 for kk=1:N
  k=ids(kk);j=str2double(d.spec.suite(2:end));
  if j==9
   seed=jog.Core.seed(cfg,9,d.spec.condition_id,k);rng(seed,'twister');
   zl=randn(size(no.F_local,2),1);zb=randn(size(no.L_b,2),1);b.rng_id(:,kk)=[seed;seed];
  else
   [r,sid]=jog2.Util.stream(cfg,j,d.spec.geometry_id,d.spec.rng_coupling_id,k,1);
   % Draw max-point local arrays for nested J12/J13 comparisons.
   if any(j==[12 13]),zmax=randn(r,5,60);zl=reshape(zmax(:,1:n),[],1);else,zl=randn(r,size(no.F_local,2),1);end
   [rb,sb]=jog2.Util.stream(cfg,j,d.spec.geometry_id,d.spec.rng_coupling_id,k,2);
   zb=randn(rb,size(no.L_b,2),1);b.rng_id(:,kk)=[sid;sb];
  end
  b.z_local(:,kk)=zl;b.z_common(:,kk)=zb;b.local_errors(:,kk)=no.F_local*zl;
  b.common_effects(:,kk)=no.L_b*zb;b.eta(:,kk)=b.local_errors(:,kk)+no.G_raw*b.common_effects(:,kk);
  y=d.geometry.y_true+reshape(b.eta(:,kk),5,n);b.observations(:,:,kk)=y;
  if strcmp(cfg.nonlinear.initialization,'oracle_local'),pool={d.geometry.truth_camera};
  else,pool=jog.Camera.initialize(y,cfg);end
  for p=1:numel(pool),b.initializer_camera(:,end+1)=jog2.Util.camvec(pool{p});b.initializer_trial(end+1)=k;end
  for m=1:nm
   r=jog.solve_camera(y,d.covariance_factors{m},pool,cfg);
   b=jog2.Batch.addFit(b,r,m,kk,d.geometry.truth_camera);
   b.linear_error(:,kk,m)=d.oracle_reference{m}.sensitivity*b.eta(:,kk);
  end
 end
end
function b=addFit(b,r,m,k,truth)
 b.valid(m,k)=r.success;b.cameras(:,m,k)=jog2.Util.camvec(r.camera);
 if ~isempty(r.camera),b.errors(:,k,m)=jog.Camera.error(r.camera,truth);end
 if r.success
  b.covariance_native(:,:,k,m)=r.covariance;T=eye(10);T(4:6,4:6)=jog.Camera.leftInverse(b.errors(4:6,k,m));
  b.covariance_common(:,:,k,m)=T*r.covariance*T';
 end
 b.cost(m,k)=r.cost;b.iterations(m,k)=r.iterations;b.closure(m,k)=r.constraint_inf;
 b.stationarity(m,k)=r.stationarity_norm;b.physical(m,k)=r.physical_valid;
 b.active_bound(m,k)=r.active_parameter_bound;b.rank(m,k)=r.rank;
 b.condition_scaled(m,k)=r.condition_scaled;b.elapsed(m,k)=r.elapsed_seconds;
 b.selected_candidate(m,k)=r.selected_candidate;b.reprojection(:,:,m,k)=r.raw_reprojection;
 b.adjusted(:,:,m,k)=r.adjusted_observations;b.correction(:,:,m,k)=r.observation_correction;
 if ~isempty(r.sensitivity),b.sensitivity(:,:,m,k)=r.sensitivity;end
 a=numel(b.latent_values);b.latent_offset(:,m,k)=[a+1;numel(r.latent_error)];
 b.latent_values=[b.latent_values;r.latent_error];
 a=size(b.history_values,1);b.history_offset(:,m,k)=[a+1;size(r.history,1)];
 if ~isempty(r.history),b.history_values=[b.history_values;r.history];end
 [b,code]=jog2.Batch.status(b,r.status);b.status_code(m,k)=code;
 for j=1:numel(r.candidates)
  c=r.candidates{j};a=size(b.candidate_history,1);
  b.candidate_history_offset(:,end+1)=[a+1;size(c.history,1)];
  if ~isempty(c.history),b.candidate_history=[b.candidate_history;c.history];end
  b.candidate_camera(:,end+1)=jog2.Util.camvec(c.camera);
  ph=NaN;if isfield(c,'physical_valid'),ph=double(c.physical_valid);end
  b.candidate_info(:,end+1)=[m;b.trial_id(k);j;c.success;c.cost;c.iterations;c.constraint_inf;ph;r.selected_candidate==j];
  [b,code]=jog2.Batch.status(b,c.status);b.candidate_status_code(end+1)=code;
 end
end
function [b,c]=status(b,s)
 c=find(strcmp(b.meta.status_dictionary,s),1);
 if isempty(c),b.meta.status_dictionary{end+1}=s;c=numel(b.meta.status_dictionary);end
end
end
end

classdef Geometry
methods(Static)
function g=paired(cfg,n,spread,j,gid)
 [r,sid]=jog2.Util.stream(cfg,j,gid,0,0,0);
 uvU=rand(r,2,60);zU=rand(r,1,60);c=jog.Camera.truth(cfg);x=cfg.camera;
 patch=mod(0:59,4)+1;sg=[-1 1 -1 1;-1 -1 1 1];
 uv=sg(:,patch).*(.12+.88*uvU).*[x.width;x.height]*x.occupancy/2;
 z=x.mean_depth*(1+spread*(zU-.5));
 d=(uv-c.pp)/x.scale;a=d./(1+c.kappa*sum(d.^2,1));
 xyz=c.gamma+c.R'*[a/exp(c.phi).*z;z];
 hull=convhull(uv(1,1:n),uv(2,1:n));
 g=struct('truth_camera',c,'y_true',[uv(:,1:n);xyz(:,1:n)],...
 'patch_id',patch(1:n),'point_id',1:n,'seed',cfg.revision_seed,'substream',sid,...
 'spread_requested',spread,'depth_actual',z(1:n),'depth_cv',std(z(1:n),1)/mean(z(1:n)),...
 'image_hull_fraction',polyarea(uv(1,hull),uv(2,hull))/(x.width*x.height),...
 'master_xyz',xyz,'master_uv',uv,'master_depth_u',zU,'generator','paired_60');
end
function g=legacy(cfg,n,spread)
 seed=cfg.master_seed+200000000+n*1000+round(1000*spread);
 g=jog.Camera.geometry(cfg,n,spread,seed);g.generator='legacy_twister';
end
function [g,found]=sourceGeometry(file,n,spread)
 found=false;g=[];if isempty(file),return;end
 o=jog2.Store.metadata(file);
 if strcmp(o.schema_version,'jog-output-1.0')
  error('jog2:importFirst','Import v1 first with jog_import_v1.');
 end
 for i=1:numel(o.conditions)
  e=o.conditions{i};
  if strcmp(e.suite,'J09')&&e.spec.n==n&&abs(e.spec.depth_spread-spread)<1e-12
   d=jog2.Store.design(file,e);g=d.geometry;found=true;return;
  end
 end
end
end
end

classdef H5Legacy
%H5LEGACY Bounded subtree reader for dense structs/cells in MATLAB v7.3.
% Uses official HDF5 object references; does not load the top-level output.
methods(Static)
function v=read(file,path,indices)
 if nargin<3,indices=[];end
 info=h5info(file,path);
 if isfield(info,'Datasets')
  names={};if ~isempty(info.Datasets),names={info.Datasets.Name};end
  if ~isempty(info.Groups),names=[names {info.Groups.Name}];end;fields=struct();isref=false(1,numel(names));
  for k=1:numel(names)
   name=names{k};if startsWith(name,'/'),[~,field]=fileparts(name);child=name;else,field=name;child=[path '/' name];end
   ci=h5info(file,child);cls=jog2.H5Legacy.attribute(ci,'MATLAB_class','');
   isref(k)=isfield(ci,'Datatype')&&strcmp(ci.Datatype.Class,'H5T_REFERENCE')&&isempty(cls);
   fields.(field)=jog2.H5Legacy.read(file,child);
  end
  if any(isref)
   fn=fieldnames(fields);a=find(isref,1);shape=size(fields.(fn{a}));v=repmat(struct(),shape);
   for k=1:numel(fn)
    x=fields.(fn{k});
    for z=1:numel(v),if isref(k),v(z).(fn{k})=x{z};else,v(z).(fn{k})=x;end,end
   end
  else,v=fields;end
  return;
 end
 cls=jog2.H5Legacy.attribute(info,'MATLAB_class','');
 emptyflag=jog2.H5Legacy.attribute(info,'MATLAB_empty',0);
 if strcmp(info.Datatype.Class,'H5T_REFERENCE')
  fid=H5F.open(file);cf=onCleanup(@()H5F.close(fid));ds=H5D.open(fid,path);cd=onCleanup(@()H5D.close(ds));
  raw=H5D.read(ds);raw=reshape(raw,size(raw,1),[]);space=H5D.get_space(ds);[~,dims]=H5S.get_simple_extent_dims(space);H5S.close(space);
  shape=fliplr(dims);if numel(shape)<2,shape=[shape 1];end
  allidx=1:size(raw,2);if ~isempty(indices),allidx=indices;shape=[1 numel(indices)];end
  v=cell(shape);
  for z=1:numel(allidx)
   ref=raw(:,allidx(z));obj=H5R.dereference(ds,'H5R_OBJECT',ref);target=H5I.get_name(obj);H5O.close(obj);
   v{z}=jog2.H5Legacy.read(file,target);
  end
 else
  v=h5read(file,path);
  if emptyflag
   dims=double(v(:)');if isempty(dims),dims=[0 0];end;if numel(dims)<2,dims=[dims 0];end
   if strcmp(cls,'cell'),v=cell(dims);elseif strcmp(cls,'char'),v=char(zeros(dims));else,v=zeros(dims);end
  elseif strcmp(cls,'char'),v=char(v);
  elseif strcmp(cls,'logical'),v=logical(v);
  elseif isstruct(v)&&isfield(v,'real')&&isfield(v,'imag'),v=complex(v.real,v.imag);
  end
 end
end
function a=attribute(info,name,fallback)
 a=fallback;if isempty(info.Attributes),return;end
 idx=find(strcmp({info.Attributes.Name},name),1);
 if ~isempty(idx),a=info.Attributes(idx).Value;if isstring(a),a=char(a);end,end
end
function n=count(file,path)
 info=h5info(file,path);n=prod(info.Dataspace.Size);
end
end
end

classdef LegacyView
methods(Static)
function old=make(file,o,E)
 idx=find(cellfun(@(c)strcmp(c.suite,'J09'),o.conditions));conditions={};
 for i=idx
  c=o.conditions{i};d=jog2.Store.design(file,c);s=o.summaries{i};
  errors=[];valid=[];maxaxes=[];
  for b=1:numel(c.batches)
   raw=jog2.Store.read(file,c.batches{b});errors=cat(2,errors,raw.errors);valid=[valid raw.valid];
   axes=nan(numel(d.methods),numel(raw.trial_id));
   for m=1:numel(d.methods)
    for k=find(raw.valid(m,:))
     ev=eig(raw.covariance_native(1:3,1:3,k,m));axes(m,k)=sqrt(jog.Core.chi2(.95,3)*max(ev));
    end
   end
   maxaxes=[maxaxes axes];
  end
  ss=cell(size(s.method));
  for m=1:numel(ss)
   a=s.method{m};z=a.blocks.full;z.position=a.blocks.position;z.eop=a.blocks.eop;
   z.raw_reprojection_coordinate_rmse=a.reprojection_rmse;z.position_error_norm=sqrt(sum(errors(1:3,:,m).^2,1));
   z.median_maxaxis95=jog.Core.quantile(maxaxes(m,:),.5);ss{m}=z;
  end
  conditions{end+1}=struct('spec',c.spec,'methods',{d.methods},'summary',{ss},...
   'valid',valid,'errors',errors,'oracle_reference',{d.oracle_reference});
 end
 if ~isempty(conditions),E.J09=struct('conditions',{conditions});end
 cfg=o.config;cfg.fig_dpi=300;old=struct('config',cfg,'experiments',E);
end
end
end

classdef Noise
methods(Static)
function s=spec(cfg,kind)
 x=cfg.camera;s=struct('kind',kind,'image_std',x.local_image_std,...
 'xyz_std',x.local_xyz_std,'anisotropy',x.anisotropy,'patch_std',x.patch_std,...
 'global_std',x.global_std,'scale',1,'alpha',1,'groups',4,'length_factor',1,...
 'image_extent',[x.width;x.height]*x.occupancy/2,'rotation_std',0,'translation_std',0,'scale_std',0,'pivot',[],'Qb_override',[]);
end
function no=build(g,s)
 n=size(g.y_true,2);a=s.anisotropy;
 qx=s.xyz_std^2*diag([3 3 3*a*a]/(2+a*a));
 Ql=kron(eye(n),blkdiag(s.image_std^2*eye(2),qx))*s.scale^2;
 xyz=reshape(1:5*n,5,n);ix=xyz(3:5,:);ix=ix(:);
 G=zeros(5*n,0);qb=zeros(0);labels={};comp={};
 switch s.kind
 case 'none'
 case {'patch','global','patch_global'}
  if any(strcmp(s.kind,{'patch','patch_global'}))
   ids=jog2.Noise.partition(g,s.groups,s.image_extent);ng=max(ids);Gp=zeros(3*n,3*ng);
   for i=1:n,Gp(3*i-2:3*i,3*ids(i)-2:3*ids(i))=eye(3);end
   G0=zeros(5*n,3*ng);G0(ix,:)=Gp;G=[G G0];qb=blkdiag(qb,s.patch_std^2*eye(3*ng));
   labels=[labels arrayfun(@(i)sprintf('patch_%d',i),1:3*ng,'UniformOutput',false)];
   comp{end+1}=struct('name','patch','columns',1:3*ng);
  end
  if any(strcmp(s.kind,{'global','patch_global'}))
   start=size(G,2);G0=zeros(5*n,3);G0(ix,:)=repmat(eye(3),n,1);
   G=[G G0];qb=blkdiag(qb,s.global_std^2*eye(3));labels=[labels {'tx','ty','tz'}];
   comp{end+1}=struct('name','global','columns',start+(1:3));
  end
 case 'similarity'
  G=zeros(5*n,7);
  for i=1:n,v=g.y_true(3:5,i)-s.pivot;G(5*i-2:5*i,:)=[-jog.Camera.skew(v),eye(3),v];end
  qb=blkdiag(s.rotation_std^2*eye(3),s.translation_std^2*eye(3),s.scale_std^2);
  if ~isempty(s.Qb_override),qb=s.Qb_override;end
  labels={'omega_x','omega_y','omega_z','tx','ty','tz','scale'};
  comp={struct('name','similarity','columns',1:7)};
 case 'spatial'
  X=g.y_true(3:5,:);dist=sqrt(max(0,sum(X.^2,1)'+sum(X.^2,1)-2*X'*X));
  dm=jog.Core.quantile(dist(triu(true(n),1)&dist>0),.5);assert(dm>0);
  ell=s.length_factor*dm;K=exp(-dist/ell);
  G=zeros(5*n,3*n);G(ix,:)=eye(3*n);qb=s.patch_std^2*kron(K,eye(3));
  labels=arrayfun(@(i)sprintf('spatial_%d',i),1:3*n,'UniformOutput',false);
  comp={struct('name','spatial','columns',1:3*n)};
 otherwise,error('jog2:noiseKind','Unknown noise kind: %s',s.kind);
 end
 qb=qb*s.scale^2*s.alpha;L=jog2.Util.psdfactor(qb);
 Fl=jog2.Util.psdfactor(Ql);Fc=G*L;Q=Ql+Fc*Fc';
 no=struct('Q_local',Ql,'G_raw',G,'Q_b',qb,'F_local',Fl,'F_common',Fc,...
 'L_b',L,'Q_full',Q,'kind',s.kind,'spec',s,'common_labels',{labels},'components',{comp},...
 'factor_local_columns',1:size(Fl,2),'factor_common_columns',size(Fl,2)+(1:size(Fc,2)),...
 'latent_to_b',L,'observation_order','point-major [u,v,X,Y,Z]');
end
function ids=partition(g,groups,bound)
 uv=g.y_true(1:2,:);
 if groups==4,ids=g.patch_id;
 elseif groups==2,ids=1+(uv(1,:)>=0);
 elseif any(groups==[9 16])
  a=round(sqrt(groups));
  bins=min(a,max(1,floor((uv+bound)./(2*bound)*a)+1));
  ids=bins(1,:)+a*(bins(2,:)-1);
 else,error('jog2:groups','Use 2,4,9,16 groups');end
 [~,~,ids]=unique(ids);ids=ids(:)';
end
function [F,meta]=factor(no,method)
 F=jog.Camera.factor(no,method);
 meta=struct('method',method,'local_columns',[],'common_columns',[],'latent_to_b',[]);
 if strcmp(method,'GH_FULL')
  meta.local_columns=no.factor_local_columns;meta.common_columns=no.factor_common_columns;
  meta.latent_to_b=no.L_b;
 end
end
function r=reference(g,no,F,cfg)
 [~,A,B]=jog.Camera.evaluate(g.y_true,g.truth_camera);S=B*(F*F')*B';L=chol((S+S')/2,'lower');
 [C,~,rank,cond]=jog.Core.normal(L\A,cfg.solver.rank_tolerance);
 W=C*(L\A)'/L*B;actual=W*no.Q_full*W';
 r=struct('A',A,'B',B,'S_assumed',S,'nominal_covariance',C,...
 'actual_sampling_covariance',(actual+actual')/2,'sensitivity',W,...
 'rank',rank,'condition_scaled',cond,'design_is_oracle',true);
end
function d=decompose(g,no,cfg,cols)
 if nargin<4,cols=1:10;end
 [~,A,B]=jog.Camera.evaluate(g.y_true,g.truth_camera);L=chol(B*no.Q_local*B','lower');
 % Use independent positive-support latent coordinates: covariance I.
 U=B*no.G_raw*no.L_b;d=jog.Core.linear(L\A(:,cols),L\U,eye(size(U,2)));
 d.Gamma=d.T;d.support_to_physical=no.L_b;d.parameter_columns=cols;
 d.whitening='local';d.design='truth';d.rank_tolerance=cfg.solver.rank_tolerance;
end
end
end

classdef Plan
methods(Static)
function cases=make(id,cfg)
 cases={};base=jog2.Noise.spec(cfg,'patch');reg=cfg.j10.regimes;bn=cfg.nonlinear.baseline_points;bd=cfg.nonlinear.baseline_spread;
 switch id
 case 'J09'
  for a=cfg.nonlinear.noise_scales,add(bn,bd,a,'noise_scale',a,0,0,base);end
  for d=cfg.nonlinear.depth_spreads,if d~=bd,add(bn,d,1,'depth_spread',d,0,0,base);end,end
  for n=cfg.nonlinear.point_counts,if n~=bn,add(n,bd,1,'point_count',n,0,0,base);end,end
  b=base;b.kind='global';for n=cfg.nonlinear.point_counts,add(n,bd,1,'global_translation',n,0,0,b);end
 case 'J10'
  for g=1:size(reg,1)
   for a=cfg.j10.scales,add(reg(g,1),reg(g,2),a,'weak_noise',a,g,0,base);end
  end
 case 'J11'
  add(30,.15,1,'M1',1,1,0,base);v={};
  for a=cfg.j11.alpha,b=base;b.alpha=a;v{end+1}=variant('GH_FULL',sprintf('FULL_alpha_%g',a),b);end
  v=[v {variant('GH_LOCAL','GH_LOCAL',base),variant('GH_MARGDIAG','GH_MARGDIAG',base),variant('FIXED3D_WLS','FIXED3D_WLS',base)}];
  cases{end}.variants=v;
  b=base;b.kind='patch_global';add(30,.15,1,'M4',1,1,1,b);
  p=b;p.kind='patch';q=b;q.kind='global';
  cases{end}.variants={variant('GH_FULL','FULL_correct',b),variant('GH_FULL','omit_global',p),...
   variant('GH_FULL','omit_patch',q),variant('GH_LOCAL','GH_LOCAL',b)};
  if ismember('M2',cfg.j11.extensions)
   add(30,.15,1,'M2',1,1,0,base);v={variant('GH_FULL','correct_4',base)};
   for ng=cfg.j11.groups,b=base;b.groups=ng;v{end+1}=variant('GH_FULL',sprintf('groups_%d',ng),b);end
   cases{end}.variants=v;
  end
  if ismember('M3',cfg.j11.extensions)
   add(30,.15,1,'M3',1,1,0,base);v={variant('GH_FULL','correct_patch',base)};
   for f=cfg.j11.length_factors,b=base;b.kind='spatial';b.length_factor=f;v{end+1}=variant('GH_FULL',sprintf('spatial_%g',f),b);end
   cases{end}.variants=v;
  end
  if ismember('M5',cfg.j11.extensions)
   b=base;b.kind='spatial';add(30,.15,1,'M5',1,1,2,b);
   cases{end}.variants={variant('GH_FULL','correct_spatial',b),variant('GH_FULL','assume_patch',base),...
    variant('GH_LOCAL','GH_LOCAL',b),variant('GH_MARGDIAG','GH_MARGDIAG',b)};
  end
 case 'J12'
  for g=1:cfg.j12.geometries
   for a=1:size(cfg.j12.regimes,1)
    rr=cfg.j12.regimes(a,:);add(rr(1),rr(2),1,'geometry_population',a,g,0,base);
    cases{end}.N=cfg.j12.maps;
   end
  end
 case 'J13'
  for d=cfg.j13.rotation_deg
   for n=cfg.j13.points
    b=base;b.kind='similarity';b.rotation_std=d*pi/180;
    b.translation_std=cfg.j13.translation_std;b.scale_std=cfg.j13.scale_std;
    add(n,.15,1,'similarity_rotation',d,1,0,b);
   end
  end
 case 'J14'
  for k=1:size(cfg.j14.scenarios,1)
   v=cfg.j14.scenarios(k,:);b=base;b.kind='patch_global';
   b.xyz_std=v(1);b.patch_std=v(2);b.global_std=v(3);
   add(30,.15,1,'shared_strength',k,1,0,b);
  end
