function [manifest,data]=render(asset,panels,caption,o,dest)
 cfg=o.config;data=struct('asset_id',asset,'panels',{panels},'caption',caption,...
 'run_id',o.meta.run_id,'config_hash',o.meta.config_hash,'nominal',cfg.nominal,...
