 clean=onCleanup(@()close(f));tiledlayout(nr,nc,'TileSpacing','compact','Padding','compact');
 colors=[0 .447 .698;.835 .369 0;0 .62 .45;.8 .475 .655;.35 .35 .35;.9 .65 0;.1 .6 .8;.5 .3 .2];
 for i=1:numel(panels)
