function file=jog_realdata_v2(data,cfg,destination)
%JOG_REALDATA_V2 Optional R01 adapter: measured y + externally supplied Q.
% data.y: 5xn [u;v;X;Y;Z], centered pixels/metres.
% data.Q_local, data.G_raw, data.Q_b, data.covariance_provenance required.
% No empirical camera coverage is inferred from a single real map.
required={'y','Q_local','G_raw','Q_b','covariance_provenance'};
for k=1:numel(required),assert(isfield(data,required{k}),'Missing real-data field %s',required{k});end
assert(size(data.y,1)==5&&size(data.y,2)>=6);
no=struct('Q_local',data.Q_local,'G_raw',data.G_raw,'Q_b',data.Q_b);
no.F_local=jog2.Util.psdfactor(no.Q_local);no.F_common=no.G_raw*jog2.Util.psdfactor(no.Q_b);
no.Q_full=no.Q_local+no.F_common*no.F_common';
pool=jog.Camera.initialize(data.y,cfg);fits=cell(size(cfg.nonlinear.methods));
for m=1:numel(fits),F=jog.Camera.factor(no,cfg.nonlinear.methods{m});fits{m}=jog.solve_camera(data.y,F,pool,cfg);end
if ~exist(destination,'dir'),mkdir(destination);end
output=struct('schema_version','jog-real-2.0','config',cfg,'data',data,'noise_model',no,...
 'methods',{cfg.nonlinear.methods},'initializers',{pool},'fits',{fits},...
 'meta',struct('dataset_type','real_single_map','created_utc',jog2.Util.utc(),...
 'source_code',jog2.Util.sources(),'coverage_claim','not estimated from one map',...
 'complete',true,'covariance_source',data.covariance_provenance));
file=fullfile(destination,'output.mat');assert(~exist(file,'file'),'Destination exists');save(file,'output','-v7.3');
end

function file=jog_recover_v2(source,destination,varargin)
% Recover completed raw simulations from v2.0 or v2.1 checkpoints.
% NEVER modifies source files and NEVER invokes a camera solver.
p=inputParser;addParameter(p,'Analyze',true);addParameter(p,'MakeFigures',true);
addParameter(p,'SourceRuns',[]);addParameter(p,'CheckIntegrity',true);addParameter(p,'MaxPackEntries',Inf);parse(p,varargin{:});
if isfolder(source),checkpoint=fullfile(source,'checkpoint.mat');
elseif endsWith(source,'checkpoint.mat'),checkpoint=source;
else,checkpoint=fullfile(fileparts(source),'checkpoint.mat');end
assert(exist(checkpoint,'file')==2,'checkpoint.mat and checkpoints/ are required. Select the original run folder.');
if nargin<2||isempty(destination)
 destination=fullfile(pwd,'results',['recovered_' datestr(now,'yyyymmdd_HHMMSS')]);
end
original=jog2.Store.metadata(checkpoint);jog2.Store.assertRawComplete(original);
fprintf('Recover raw run %s | %d conditions | no simulation will run\n',original.meta.run_id,numel(original.conditions));
% Old source-run merging requires separate conversion; never silently omit it.
sources=original.config.source_runs;
if ~isempty(p.Results.SourceRuns)
 assert(iscell(p.Results.SourceRuns)&&numel(p.Results.SourceRuns)==numel(sources),'Provide one converted archive for every original source run');
 sources=p.Results.SourceRuns;
end
for k=1:numel(sources),assert(jog2.Archive.isArchive(sources{k}),'Convert each old source run separately before merged recovery');end
file=jog2.Store.packCheckpoint(checkpoint,destination,sources,p.Results.MaxPackEntries);
if endsWith(file,'output.packing.mat'),return;end
if p.Results.Analyze,jog_analyze_v2(file);end
if p.Results.MakeFigures
 o=jog2.Store.metadata(file);assert(isfield(o.meta,'analysis_complete')&&o.meta.analysis_complete,'Complete analysis before rendering');
 jog_make_figures_v2(file,'paper');
end
if p.Results.CheckIntegrity,jog_check_output_v2(file);end
fprintf('Recovered: %s\n',file);
end

function report=jog_selftest(cfg)
%JOG_SELFTEST Fast prerequisites: algebra, Jacobians, guard and initializer.
if nargin==0,cfg=jog_config('smoke');end
rng(cfg.master_seed,'twister');g=jog.Camera.geometry(cfg,30,.3,cfg.master_seed);
c=g.truth_camera;y=g.y_true;[psi,A,B,ok]=jog.Camera.evaluate(y,c);
assert(ok && norm(psi,inf)<1e-12,'Noiseless projection failed.');
An=zeros(size(A));Bn=zeros(size(B));
for j=1:10
 h=1e-5;if j==7||j==8||ismember(j,4:6),h=1e-6;end
 dx=zeros(10,1);dx(j)=h;
 pp=jog.Camera.evaluate(y,jog.Camera.step(c,dx));pm=jog.Camera.evaluate(y,jog.Camera.step(c,-dx));
 An(:,j)=-(pp-pm)/(2*h);
end
for j=1:numel(y)
 h=1e-5;if mod(j-1,5)<2,h=1e-4;end
 yp=y;ym=y;yp(j)=yp(j)+h;ym(j)=ym(j)-h;
 Bn(:,j)=(jog.Camera.evaluate(yp,c)-jog.Camera.evaluate(ym,c))/(2*h);
end
errA=max(abs(A(:)-An(:)));errB=max(abs(B(:)-Bn(:)));
assert(errA<1e-7 && errB<1e-7,'Camera Jacobian check failed.');
no=jog.Camera.noiseModel(cfg,g,1,'global');L=chol(B*no.Q_local*B','lower');
d=jog.Core.linear(L\A,L\(B*no.G_raw),no.Q_b);
assert(jog.Core.relative(d.Sigma,d.Sigma_direct)<1e-7);
assert(jog.Core.relative(d.W,d.W_direct)<1e-7);
% Local truth-initialized zero-noise run checks adjustment, not practical initialization.
fit=jog.solve_camera(y,jog.Camera.factor(no,'GH_FULL'),{c},cfg);
assert(fit.success && norm(jog.Camera.error(fit.camera,c))<1e-8,'Noiseless GHM failed.');
pool=jog.Camera.initialize(y,cfg);assert(~isempty(pool),'Observed DLT produced no initializer.');
practical=jog.solve_camera(y,jog.Camera.factor(no,'GH_FULL'),pool,cfg);
assert(practical.success,'Observed DLT + noiseless adjustment failed.');
assert(norm(jog.Camera.error(practical.camera,c))<1e-4,'Noiseless parameter recovery failed.');
% Force the plane guard to fail: finite fallback moments, no spurious coverage.
probe=cfg;probe.mc_plane=2;probe.plane.global_stds=0;probe.plane.guard_lambda=[.01 .1];
guardTest=jog.plane_suite('J08',probe);gs=guardTest.conditions{1};
assert(~any(gs.guard_accepted) && gs.summary_all_including_fallback.n_valid==2);
assert(gs.summary_all_including_fallback.n_covariance_valid==0);
assert(all(gs.summary_all_including_fallback.coverage_operational==0));
assert(gs.summary_known_f.n_covariance_valid==0,'Fallback issued a confidence region.');
report=struct('passed',true,'guard_failure_bookkeeping_passed',true,'max_A_difference',errA,'max_B_difference',errB,...
 'GLS_covariance_relative_difference',jog.Core.relative(d.Sigma,d.Sigma_direct),...
 'observed_initializer_count',numel(pool),'noiseless_parameter_error',norm(jog.Camera.error(practical.camera,c)),...
 'note','Deterministic prerequisites only; production Monte Carlo is separate.');
disp(report);
end

function report=jog_selftest_v2(cfg)
if nargin==0,cfg=jog_config_v2('smoke');end
report.legacy=jog_selftest(cfg);
g=jog2.Geometry.paired(cfg,30,.15,13,1);
s=jog2.Noise.spec(cfg,'similarity');s.pivot=mean(g.master_xyz,2);
s.rotation_std=.005*pi/180;s.translation_std=.02;s.scale_std=20e-6;
no=jog2.Noise.build(g,s);[~,A,B]=jog.Camera.evaluate(g.y_true,g.truth_camera);
rr=g.truth_camera.gamma-s.pivot;T=zeros(10,7);T(1:3,:)=[-jog.Camera.skew(rr),eye(3),rr];T(4:6,1:3)=-g.truth_camera.R;
report.similarity_loading=jog.Core.relative(A*T,B*no.G_raw);
shift=[20;0;0];M=eye(7);M(4:6,1:3)=-jog.Camera.skew(shift);M(4:6,7)=shift;
s.pivot=s.pivot+shift;s.Qb_override=M*no.Q_b*M';no2=jog2.Noise.build(g,s);
report.pivot=jog.Core.relative(no.Q_full,no2.Q_full);
F=jog.Camera.factor(no,'GH_FULL');ref=jog2.Noise.reference(g,no,F,cfg);
report.nominal_sandwich=jog.Core.relative(ref.nominal_covariance,ref.actual_sampling_covariance);
s=jog2.Noise.spec(cfg,'patch');tr=jog2.Noise.build(g,s);s.alpha=4;as=jog2.Noise.build(g,s);
ref=jog2.Noise.reference(g,tr,jog.Camera.factor(as,'GH_FULL'),cfg);
e=eig((ref.nominal_covariance-ref.actual_sampling_covariance+ref.nominal_covariance'-ref.actual_sampling_covariance')/2);
report.inflation_min_eigenvalue=min(e);
s=jog2.Noise.spec(cfg,'patch_global');s.patch_std=0;s.global_std=0;no=jog2.Noise.build(g,s);
report.zero_psd_factor=size(no.L_b,2);assert(isempty(no.L_b));
[r,a]=jog2.Util.stream(cfg,12,1,0,1,1);v=randn(r,20,1);
[r,b]=jog2.Util.stream(cfg,12,1,0,1,1);assert(isequal(v,randn(r,20,1))&&a==b);
assert(report.similarity_loading<1e-9&&report.pivot<1e-10&&report.nominal_sandwich<1e-8);
assert(report.inflation_min_eigenvalue>-1e-7);
t=jog2.Target.design(g,cfg);report.target_step_halving=struct();
for kind={'plane','image'}
 [~,J1]=jog2.Target.values(g.truth_camera,t,kind{1},1);[~,J2]=jog2.Target.values(g.truth_camera,t,kind{1},.5);
 discrepancy=jog.Core.relative(J1(:),J2(:));report.target_step_halving.(kind{1})=discrepancy;
 assert(discrepancy<1e-5,'Target numerical derivative failed step-halving');
end
report.passed=true;
end

function report=jog_verify_v2(destination)
%JOG_VERIFY_V2 Reproducible integration tests; small MC only, not paper claims.
if nargin<1,destination=fullfile(tempdir,['jog_v2_verify_' datestr(now,'yyyymmdd_HHMMSS_FFF')]);end
if ~exist(destination,'dir'),mkdir(destination);end
cfg=jog_config_v2('smoke');cfg.j11.extensions={'M2','M3','M5'};
file=run_jog_v2(cfg,fullfile(destination,'full_smoke'));
jog_make_figures_v2(file,'legacy');
report.full_integrity=jog_check_output_v2(file);
o=jog2.Store.metadata(file);ids={o.figure_manifest.asset_id};
required=arrayfun(@(n)sprintf('F%02d',n),1:15,'UniformOutput',false);
assert(all(ismember(required,ids)),'Missing required paper assets');
assert(numel(o.legacy_figure_manifest)==16,'Missing legacy diagnostic figures');
report.figure_ids=ids;report.legacy_png_count=16;
% Resume must be equal to fresh execution for numeric scientific arrays.
small=jog_config_v2('smoke');small.enabled={'J10'};small.j10.regimes=[30 .15];
small.j10.scales=[.1 1];small.batch_size=1;small.make_figures=false;small.analyze=false;
paused=fullfile(destination,'resume');fresh=fullfile(destination,'fresh');
run_jog_v2(small,paused,'MaxBatches',1);
continued=run_jog_v2('resume',paused);complete=run_jog_v2(small,fresh);
a=jog2.Store.metadata(continued);b=jog2.Store.metadata(complete);
for c=1:numel(a.conditions)
 for k=1:numel(a.conditions{c}.batches)
  aa=jog2.Store.read(continued,a.conditions{c}.batches{k});bb=jog2.Store.read(complete,b.conditions{c}.batches{k});
  for name={'observations','eta','errors','covariance_native','candidate_camera','cost','valid'}
   assert(isequaln(aa.(name{1}),bb.(name{1})),'Resume/fresh mismatch in %s',name{1});
  end
 end
end
report.resume_equals_fresh=true;
% Single MAT copied to a clean folder must be enough to regenerate.
portable=fullfile(destination,'portable');mkdir(portable);copyfile(file,fullfile(portable,'output.mat'));
report.portable_integrity=jog_check_output_v2(fullfile(portable,'output.mat'));
report.self_contained=true;
% Optional advanced algorithms, deliberately tiny budget.
opt=cfg.j16;opt.modules={'hessian','reparameterization','bootstrap','profile'};
opt.outer_maps=1;opt.inner_maps=3;opt.max_directions=2;opt.steps=[.02 .01];
advanced=jog_advanced_v2(completeAdvancedSource(file,destination),opt);
report.advanced_smoke_modules=advanced.modules;
report.advanced_smoke_only=true;
report.completed_utc=jog2.Util.utc();report.status='passed';report.matlab_version=version;
out=fullfile(destination,'verification.json');f=fopen(out,'w');cl=onCleanup(@()fclose(f));
fprintf(f,'%s',jsonencode(report,PrettyPrint=true));disp(report);
end
function file=completeAdvancedSource(src,dest)
file=fullfile(dest,'advanced.mat');copyfile(src,file);
end

function outputFile=run_jog(profile,outputDir)
%RUN_JOG Run all experiments, save output.mat, and export PNG figures.
%   run_jog('smoke')         % Full pathway with very few trials
%   run_jog('pilot')         % Independent pilot seeds
%   run_jog('paper')         % Proposed final counts, separate seeds
%   cfg=jog_config('paper'); cfg.mc_nonlinear=500; run_jog(cfg,'my_run')
%   run_jog('resume','my_run/output.mat')  % Same saved config/code only
%
% The only top-level MAT variable is `output`. It contains configuration,
% source snapshots, all generated data, trial results, full covariances,
% failures, summaries, and figure data. No Statistics/Optimization Toolbox.
if nargin<1,profile='pilot';end
root=fileparts(mfilename('fullpath'));addpath(root);
resuming=ischar(profile)&&strcmp(profile,'resume');
source=snapshot(root);
if resuming
 if nargin<2,error('Pass the existing output.mat path.');end
 outputFile=char(outputDir);loaded=load(outputFile,'output');output=loaded.output;
 cfg=output.config;outputDir=fileparts(outputFile);
 assert(strcmp(output.schema_version,'jog-output-1.0'),'Incompatible schema.');
 assert(isequal(source,output.meta.source_code),'Code has changed: start a new run rather than mixing implementations.');
else
 if isstruct(profile),cfg=profile;else,cfg=jog_config(profile);end
 if nargin<2||isempty(outputDir)
  outputDir=fullfile(pwd,'results',[cfg.profile '_' datestr(now,'yyyymmdd_HHMMSS_FFF')]);
 end
 if ~exist(outputDir,'dir'),mkdir(outputDir);end
 outputFile=fullfile(outputDir,'output.mat');
 assert(~exist(outputFile,'file'),'Output exists. Use resume or a new directory.');
 assert(cfg.mc_linear<10000 && cfg.mc_plane<10000 && cfg.mc_nonlinear<10000,'Seed scheme supports <10000 trials.');
 output=struct('schema_version',cfg.schema_version,'config',cfg,'experiments',struct(),...
  'figure_data',struct(),'figure_manifest',struct([]));
 output.meta=struct('created',datestr(now,30),'completed','','status','initializing',...
  'matlab_version',version,'computer',computer,'toolboxes',ver,'source_code',source,...
  'uncertainty_scale','Absolute covariance, sigma0_squared=1; never residual-rescaled',...
  'parameter_order',{{'gamma_x','gamma_y','gamma_z','alpha_x','alpha_y','alpha_z','log_f_over_scale','kappa','pp_u','pp_v'}},...
  'parameter_units',{{'m','m','m','rad','rad','rad','dimensionless','dimensionless','px','px'}},...
  'rotation_chart','Left SO(3). Native covariance at estimate; moments use truth log-error chart.',...
  'independent_unit','A complete independent map/common-error and local-error realization',...
  'seed_scheme','master + suite*10000000 + condition*10000 + trial',...
  'geometry_seed_scheme','master + 200000000 + n*1000 + round(1000*spread); fixed within condition',...
  'known_limitations',{{'Literature novelty is not evaluated by this code.',...
  'J09 uses GN covariance and a local optimizer; global optimality is not guaranteed.',...
  'L2 uses exact Gaussian sufficient statistics and explicit guards.',...
  'Legacy E1, robust E5, estimated-covariance E7 and real data are outside the J-suite.'}});
 output.progress=struct('completed_ids',{{}},'current_id','','completed_J09_conditions',0);
end
start=tic;
try
 if ~isfield(output,'selftest')
  output.selftest=jog_selftest(cfg);checkpoint();
 end
 for i=1:numel(cfg.enabled)
  id=cfg.enabled{i};if ismember(id,output.progress.completed_ids),continue;end
  output.progress.current_id=id;output.meta.status='running';checkpoint();
  fprintf('\n%s | profile %s\n',id,cfg.profile);
  switch id
   case {'J00','J01','J02','J03','J04','J05','J06'}
    output.experiments.(id)=jog.linear_suite(id,cfg);
   case {'J07','J08'}
    output.experiments.(id)=jog.plane_suite(id,cfg);
   case 'J09'
    prev=[];if isfield(output.experiments,'J09'),prev=output.experiments.J09;end
    output.experiments.J09=jog.nonlinear_suite(cfg,@nonlinearCheckpoint,prev);
   otherwise,error('Unknown experiment %s',id);
  end
  output.progress.completed_ids{end+1}=id;checkpoint();
 end
 output.meta.status='rendering';checkpoint();
 [output.figure_manifest,output.figure_data]=jog_make_figures(output,fullfile(outputDir,'figures'));
 output.meta.status='complete';output.meta.completed=datestr(now,30);
 output.meta.last_session_seconds=toc(start);output.progress.current_id='';checkpoint();
 jog_check_output(outputFile);
 fprintf('\nSaved: %s\nUpload this output.mat for interpretation.\n',outputFile);
catch ME
 output.meta.status='failed';output.meta.last_error=struct('identifier',ME.identifier,'message',ME.message,'stack',ME.stack);
 output.meta.last_session_seconds=toc(start);checkpoint();rethrow(ME);
end
 function nonlinearCheckpoint(partial)
  output.experiments.J09=partial;output.progress.completed_J09_conditions=numel(partial.conditions);checkpoint();
 end
 function checkpoint()
  output.meta.last_checkpoint=datestr(now,30);
  tmp=[outputFile '.partial.mat'];save(tmp,'output','-v7.3');movefile(tmp,outputFile,'f');
 end
end
function s=snapshot(root)
files=[dir(fullfile(root,'*.m'));dir(fullfile(root,'+jog','*.m'))];
s=struct('name',{},'text',{});
for i=1:numel(files)
 fn=fullfile(files(i).folder,files(i).name);rel=fn(numel(root)+2:end);
 s(i).name=rel;s(i).text=fileread(fn);
end
[~,ix]=sort({s.name});s=s(ix);
end

function outputFile=run_jog_v2(profile,outputDir,varargin)
%RUN_JOG_V2 Complete standalone legacy + revision experiment package.
% run_jog_v2('smoke'); cfg=jog_config_v2('paper'); run_jog_v2(cfg,folder);
% run_jog_v2('resume',folder) resumes exact config/source from checkpoints.
if nargin<1,profile='smoke';end
root=fileparts(mfilename('fullpath'));addpath(root);
p=inputParser;addParameter(p,'MaxBatches',Inf);parse(p,varargin{:});
resuming=(ischar(profile)||isstring(profile))&&strcmp(profile,'resume');
if resuming
 if nargin<2,error('Pass run folder');end
 o=jog2.Store.metadata(fullfile(outputDir,'checkpoint.mat'));cfg=o.config;
 assert(strcmp(o.meta.source_hash,jog2.Util.hash(jsonencode(jog2.Util.sources()))),'Source changed: start a separate run');
else
 if isstruct(profile),cfg=profile;else,cfg=jog_config_v2(char(profile));end
 jog2.Validate.config(cfg);
 if nargin<2||isempty(outputDir),outputDir=fullfile(pwd,'results',[cfg.profile '_' datestr(now,'yyyymmdd_HHMMSS_FFF')]);end
 o=jog2.Store.create(cfg,outputDir);o.validation.selftest=jog_selftest_v2(cfg);
 o.validation.preflight=jog2.Validate.preflight(cfg,outputDir);
 jog2.Store.checkpoint(o,outputDir);
end
limit=min(cfg.max_batches_per_session,p.Results.MaxBatches);done=0;t=tic;
try
 for si=1:numel(cfg.enabled)
  id=cfg.enabled{si};if any(strcmp(id,{'J15','J16'})),continue;end
  if ismember(id,o.progress.completed_suites),continue;end
  j=str2double(id(2:end));fprintf('\n%s / %s\n',id,cfg.profile);
  if j<9
   if j<7,x=jog.linear_suite(id,cfg);else,x=jog.plane_suite(id,cfg);end
   prefix=[o.meta.run_id '_' id];[e,~]=jog2.Store.write(outputDir,prefix,x);
   o.legacy.(id)=e;o.progress.completed_suites{end+1}=id;jog2.Store.checkpoint(o,outputDir);continue;
  end
  cases=jog2.Plan.make(id,cfg);
  for ci=1:numel(cases)
   idx=find(cellfun(@(c)strcmp(c.suite,id)&&c.spec.condition_id==ci,o.conditions),1);
   if isempty(idx)
    d=jog2.Plan.prepare(cases{ci},cfg);prefix=sprintf('%s_%sc%03d',o.meta.run_id,id,ci);
    [entry,~]=jog2.Store.write(outputDir,[prefix '_design'],d);
    c=struct('suite',id,'spec',d.spec,'prefix',prefix,'design',entry,'batches',{{}},...
     'completed_trial_ids',[],'run_id',o.meta.run_id);
    o.conditions{end+1}=c;idx=numel(o.conditions);jog2.Store.checkpoint(o,outputDir);
   else,c=o.conditions{idx};d=jog2.Store.design(fullfile(outputDir,'checkpoint.mat'),c);end
   remaining=setdiff(1:c.spec.N,c.completed_trial_ids);
   for first=1:cfg.batch_size:numel(remaining)
    ids=remaining(first:min(first+cfg.batch_size-1,numel(remaining)));
    b=jog2.Batch.run(d,cfg,ids);bn=numel(c.batches)+1;
    [e,~]=jog2.Store.write(outputDir,sprintf('%s_b%04d',c.prefix,bn),b,'batch');
    e.trial_ids=ids;c.batches{end+1}=e;c.completed_trial_ids=[c.completed_trial_ids ids];
    o.conditions{idx}=c;o.meta.last_session_seconds=toc(t);jog2.Store.checkpoint(o,outputDir);
    done=done+1;fprintf('  condition %d/%d, maps %d/%d\n',ci,numel(cases),numel(c.completed_trial_ids),c.spec.N);
    if done>=limit
     o.meta.status='partial';jog2.Store.checkpoint(o,outputDir);
     outputFile=fullfile(outputDir,'checkpoint.mat');fprintf('Partial checkpoint: %s\n',outputFile);return;
    end
   end
  end
  o.progress.completed_suites{end+1}=id;jog2.Store.checkpoint(o,outputDir);
 end
 outputFile=jog_finalize_v2(outputDir,'SourceRuns',cfg.source_runs);
 if cfg.analyze,jog_analyze_v2(outputFile,{'D01','D02','D03','D04','J15'});end
 if cfg.j16.enabled&&ismember('J16',cfg.enabled),jog_advanced_v2(outputFile,cfg.j16);end
 if cfg.make_figures,jog_make_figures_v2(outputFile,'paper');end
 jog_check_output_v2(outputFile,'strict');
 fprintf('\nComplete: %s\n',outputFile);
catch ME
 o.meta.status='failed';o.meta.last_error=struct('identifier',ME.identifier,'message',ME.message,'stack',ME.stack);
 jog2.Store.checkpoint(o,outputDir);rethrow(ME);
end
end
